-- Migration: Cria e popula a tabela 'dossiers' com o conteúdo integral extraído
-- de src/components/MainView.tsx (mockCards) do protótipo React do CHRONOS.
-- Sprint: 5.2.2
-- Date: 30/07/2026
-- Author: Equipe de Engenharia CHRONOS (extração automatizada via scripts/extract_dossiers.js)

BEGIN;

CREATE TABLE IF NOT EXISTS dossiers (
    id VARCHAR(255) PRIMARY KEY,
    category VARCHAR(255) NOT NULL,
    period VARCHAR(255) NOT NULL,
    title TEXT NOT NULL,
    era VARCHAR(255) NOT NULL,
    summary TEXT NOT NULL,
    evidence_level VARCHAR(50) NOT NULL,
    fact JSONB NOT NULL,
    interpretation JSONB NOT NULL,
    hypothesis JSONB NOT NULL,
    timeline JSONB NOT NULL DEFAULT '[]'::jsonb,
    characters JSONB NOT NULL DEFAULT '[]'::jsonb,
    sources JSONB NOT NULL DEFAULT '[]'::jsonb,
    publication_status VARCHAR(50) NOT NULL DEFAULT 'published',
    ativo BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_dossiers_period ON dossiers(period);
CREATE INDEX IF NOT EXISTS idx_dossiers_category ON dossiers(category);

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_dossiers_updated_at ON dossiers;
CREATE TRIGGER trigger_dossiers_updated_at
BEFORE UPDATE ON dossiers
FOR EACH ROW
EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE dossiers ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS policy_dossiers_select_public ON dossiers;
CREATE POLICY policy_dossiers_select_public
ON dossiers
FOR SELECT
USING (true);

DROP POLICY IF EXISTS policy_dossiers_insert_authenticated ON dossiers;
CREATE POLICY policy_dossiers_insert_authenticated
ON dossiers
FOR INSERT
TO authenticated
WITH CHECK (true);

DROP POLICY IF EXISTS policy_dossiers_update_authenticated ON dossiers;
CREATE POLICY policy_dossiers_update_authenticated
ON dossiers
FOR UPDATE
TO authenticated
USING (true)
WITH CHECK (true);

DROP POLICY IF EXISTS policy_dossiers_delete_authenticated ON dossiers;
CREATE POLICY policy_dossiers_delete_authenticated
ON dossiers
FOR DELETE
TO authenticated
USING (true);

INSERT INTO dossiers (id, category, period, title, era, summary, evidence_level, fact, interpretation, hypothesis, timeline, characters, sources, publication_status, ativo)
VALUES
('sumeria', 'História', 'Antiguidade', 'A Invenção da Escrita Cuneiforme (c. 3200 a.C.)', 'Antiguidade Oriental (c. 3200 a.C.)', 'A transição de fichas contábeis de argila para tabuletas cuneiformes em Uruk. Síntese executiva sobre a necessidade de controle tributário, o mecanismo administrativo da escrita e seu impacto cognitivo e histórico.', 'high', '{"title":"O Contexto Urbano e a Transição dos Artefatos de Argila em Uruk","description":"No final do 4º milênio a.C., a cidade suméria de Uruk experimentou um boom demográfico e administrativo sem precedentes. Para gerir colheitas, tributos de cevada e rebanhos rituais do complexo do Templo de Eanna, os administradores evoluíram de fichas tridimensionais (calculi) seladas em esferas ocas de argila (bullae) para tabuletas planas marcadas com estiletes de junco em formato de cunha, originando a escrita proto-cuneiforme."}'::jsonb, '{"title":"A Teoria de Denise Schmandt-Besserat e a Revolução Cognitivo-Administrativa","description":"A arqueóloga Denise Schmandt-Besserat provou que a escrita não nasceu da literatura ou religião, mas da necessidade contábil. A transição do pictograma ao ideograma e, posteriormente, ao fonograma (princípio do rébus) permitiu registrar abstrações, leis e memórias sociais, reconfigurando a estrutura do poder estatal centralizado e a própria cognição humana."}'::jsonb, '{"title":"Origem Contábil Monogênica vs. Poligênese da Escrita","description":"Enquanto o consenso acadêmico (Hans J. Nissen e Schmandt-Besserat) corrobora a matriz contábil mesopotâmica na Baixa Mesopotâmia, debate-se se a escrita egípcia (hieróglifos c. 3250 a.C.) surgiu por estímulo cultural indireto da Suméria ou por invenção endógena independente."}'::jsonb, '[{"year":"c. 8000–3500 a.C.","event":"Uso de fichas simples de argila (calculi) para contagem de bens e grãos no Crescente Fértil."},{"year":"c. 3500–3300 a.C.","event":"Surgimento das \"bullae\" (esferas ocas de argila seladas) e fichas complexas gravadas."},{"year":"c. 3200 a.C.","event":"Primeiras tabuletas de argila com registros pictográficos e proto-cuneiforme no Templo de Eanna (Uruk IV)."},{"year":"c. 2900–2600 a.C.","event":"Desenvolvimento do fonetismo (rébus); transição de símbolos pictográficos para caracteres cuneiformes abstratos."},{"year":"c. 2600 a.C.","event":"Surgimento da literatura (Epopeia de Gilgamesh), códigos de leis primordiais e textos litúrgicos."}]'::jsonb, '[{"name":"Enmerkar","role":"Rei Lendário de Uruk","bio":"Figura mitológico-histórica a quem a tradição suméria (no poema Enmerkar e o Senhor de Aratta) atribui a invenção da escrita em argila para enviar mensagens diplomáticas imutáveis."},{"name":"Denise Schmandt-Besserat","role":"Arqueóloga e Epigrafista Contemporânea","bio":"Responsável pela teoria revolucionária de que as fichas contábeis neolíticas (tokens) deram origem direta aos sinais cuneiformes."},{"name":"Hans J. Nissen","role":"Historador e Arqueólogo (Univ. Livre de Berlim)","bio":"Líder do Projeto Uruk-Warka, responsável pela decifração do sistema contábil e socioeconômico das tabuletas arcaicas de Uruk."}]'::jsonb, '[{"id":"src-cun-1","title":"Tabuletas do Templo de Eanna (Uruk IV)","author":"Escribas de Uruk","year":-3200,"type":"archaeological","details":"Acervo do Museu do Iraque / Museu Pergamon"},{"id":"src-cun-2","title":"How Writing Came About","author":"Denise Schmandt-Besserat","year":1996,"type":"book","details":"University of Texas Press, Cap. 1-4"},{"id":"src-cun-3","title":"Archaic Bookkeeping: Early Writing and Techniques of Economic Administration in the Ancient Near East","author":"Hans J. Nissen, Peter Damerow, Robert K. Englund","year":1993,"type":"book","details":"University of Chicago Press"}]'::jsonb, 'published', true),
('roma-republica', 'História', 'Antiguidade', 'A Travessia do Rubicão e a Guerra Civil Romana (49 a.C.)', 'Antiguidade Clássica (49 a.C.)', 'A decisão de Júlio César ao cruzar o rio Rubicão com a XIII Legião, desafiando a autoridade do Senado Romano e deflagrando a Guerra Civil.', 'high', '{"title":"A Travessia da XIII Legião Gemina","description":"Em janeiro de 49 a.C., Júlio César cruzou a fronteira fluvial do Rubicão sem desmobilizar seu exército. Proclamou \"Alea iacta est\" (A sorte está lançada). A lei romana proibia severamente que generais adentrassem a Itália armados sem autorização do Senado."}'::jsonb, '{"title":"Crise Institucional da República Romana","description":"A historiografia clássica (como a obra de Ronald Syme) interpreta a travessia do Rubicão como o sintoma final do colapso da República oligárquica, cujas legiões se tornaram mais leais aos seus generais imperadores do que às instituições do Senado."}'::jsonb, '{"title":"Ultimato dos Senadores e Legítima Defesa","description":"Historiadores cesarianos sustentam que César foi encurralado pelo ultimato dos senadores conservadores (Optimates) liderados por Catão e Pompeu, os quais pretendiam processá-lo e destruí-lo politicamente assim que perdesse a imunidade proconsular."}'::jsonb, '[{"year":"50 a.C.","event":"O Senado ordena que Júlio César entregue o comando militar das legiões na Gália."},{"year":"49 a.C.","event":"César cruza o rio Rubicão com a XIII Legião em 10 de janeiro; Pompeu e o Senado evacuam a Itália."},{"year":"48 a.C.","event":"Batalha de Farsália; César derrota Pompeu e assume o controle supremo de Roma."}]'::jsonb, '[{"name":"Júlio César","role":"Proconsul da Gália e Ditador","bio":"General brilhante e estrategista político que cruzou o Rubicão, pondo fim ao modelo republicano tradicional."},{"name":"Pompeu o Grande","role":"General e Comandante do Senado","bio":"Antigo aliado do Primeiro Triunvirato que assumiu a liderança das forças republicanas contra César."},{"name":"Cleópatra VII","role":"Rainha do Egito Ptolemaico","bio":"Soberana que articulou aliança estratégica com César durante os desdobramentos da guerra no Mediterrâneo."}]'::jsonb, '[{"id":"src-ces-1","title":"Comentários sobre a Guerra Civil (Commentarii de Bello Civili)","author":"Júlio César","year":-48,"type":"document","details":"Livro I, Seções 1 a 12"},{"id":"src-ces-2","title":"A Revolução Romana (The Roman Revolution)","author":"Ronald Syme","year":1939,"type":"book","details":"Capítulo IV: The Dictator"},{"id":"src-ces-3","title":"Vida dos Doze Césares: Divus Julius","author":"Suetônio","year":121,"type":"book","details":"Seções 31 a 33"}]'::jsonb, 'published', true),
('tordesilhas', 'História', 'Idade Moderna', 'O Tratado de Tordesilhas (1494)', 'Fim do Século XV (1494)', 'A divisão diplomática e cartográfica do Novo Mundo entre as coroas de Castela e Portugal chancelada pela Igreja Católica.', 'high', '{"title":"O Acordo Diplomático Real","description":"O tratado foi assinado em 7 de junho de 1494 na vila espanhola de Tordesilhas. Os originais em pergaminho estão preservados no Archivo General de Indias em Sevilha e no Arquivo Nacional da Torre do Tombo em Lisboa, constituindo prova documental absoluta de sua assinatura."}'::jsonb, '{"title":"Interpretação Geopolítica","description":"Historiadores debatem se Portugal já tinha conhecimento prévio da existência do território sul-americano antes de 1500, o que justificaria a insistência de D. João II em mover a linha divisória papal de 100 para 370 léguas a oeste do arquipélago de Cabo Verde."}'::jsonb, '{"title":"A Tese das Viagens Secretas","description":"Alguns historiadores navais levantam a hipótese de que caravelas portuguesas realizaram incursões secretas de reconhecimento na costa leste do Brasil entre 1493 e 1494, reportando sigilosamente os ventos e correntes ao rei."}'::jsonb, '[{"year":"1493","event":"O Papa Alexandre VI promulga a bula Inter Coetera dividindo as terras descobertas."},{"year":"1494","event":"Representantes de Portugal e Castela reúnem-se na vila de Tordesilhas e redefinem o meridiano."},{"year":"1506","event":"O Papa Júlio II emite a bula Ea Quae, ratificando formalmente o tratado geopolítico."}]'::jsonb, '[{"name":"D. João II","role":"Rei de Portugal","bio":"Estrategista diplomático astuto que liderou a pressão portuguesa pela mudança da linha de partilha."},{"name":"Reis Católicos","role":"Monarcas de Aragão e Castela","bio":"Isabel I e Fernando II, os quais autorizaram as negociações após a primeira viagem de Colombo."}]'::jsonb, '[{"id":"src-tor-1","title":"História dos Descobrimentos Portugueses","author":"Jaime Cortesão","year":1960,"type":"book","details":"Volume II, Cap. IV"},{"id":"src-tor-2","title":"Tratado de Tordesillas: Pergaminho de Ratificação","author":"Chancelaria Real","year":1494,"type":"document","details":"Gaveta 15, Maço 1"},{"id":"src-tor-3","title":"Cartografia e Diplomacia no Século XV","author":"Luís de Albuquerque","year":1983,"type":"article","details":"Revista de Estudos Históricos, nº 12"}]'::jsonb, 'published', true),
('alexandria', 'História', 'Antiguidade', 'O Incêndio da Biblioteca de Alexandria', 'Século III a.C. - Século IV d.C.', 'A investigação sobre a perda material da maior biblioteca do mundo antigo. Mito de catástrofe única vs. Realidade arqueológica.', 'good', '{"title":"Destruição Progressiva Documentada","description":"O acervo sofreu múltiplos estragos e perdas progressivas ao longo de séculos, incluindo a destruição parcial acidental na guerra civil de Júlio César (48 a.C.), o cerco de Aureliano (272 d.C.) e o fechamento do Serapeum por ordem de Teodósio I (391 d.C.)."}'::jsonb, '{"title":"Análise da Decadência Material","description":"A historiografia tradicional buscava culpar um único evento traumático (como a invasão islâmica ou o fanatismo cristão). Pesquisas atuais interpretam que a biblioteca definhou gradualmente devido ao corte de subsídios públicos imperiais, falta de escribas qualificados e obsolescência dos suportes físicos de papiro."}'::jsonb, '{"title":"Dispersão Prévia de Coleções","description":"Vários helenistas argumentam que os manuscritos mais valiosos foram dispersados ou vendidos para acervos particulares em Roma, Constantinopla e Atenas muito antes da depredação final das estruturas físicas do templo egípcio."}'::jsonb, '[{"year":"48 a.C.","event":"O porto de Alexandria é incendiado durante a campanha militar de Júlio César contra Pompeu."},{"year":"272 d.C.","event":"O Imperador Aureliano devasta o distrito real (Brouchion) onde se situava a sede central."},{"year":"391 d.C.","event":"Templos pagãos são fechados e saqueados após o edito de Teodósio I, afetando a biblioteca satélite."}]'::jsonb, '[{"name":"Ptolomeu I Sóter","role":"Faraó do Egito Ptolomaico","bio":"Fundador do Museu e da Grande Biblioteca de Alexandria, estabelecendo o polo intelectual."},{"name":"Hipátia de Alexandria","role":"Matemática e Filósofa","bio":"Última grande docente vinculada às instituições académicas alexandrinas clássicas."}]'::jsonb, '[{"id":"src-ale-1","title":"The Vanished Library: A Wonder of the Ancient World","author":"Luciano Canfora","year":1989,"type":"book","details":"Páginas 85-110"},{"id":"src-ale-2","title":"Alexandria in Late Antiquity: Topography and Social Conflict","author":"Christopher Haas","year":2002,"type":"book","details":"Capítulo III"},{"id":"src-ale-3","title":"Excavations in the Royal Quarter of Alexandria","author":"Franck Goddio","year":2008,"type":"archaeological","details":"Relatório Científico IEASM"}]'::jsonb, 'published', true),
('queda-roma', 'História', 'Idade Média', 'A Queda do Império Romano do Ocidente', 'Século V (476 d.C.)', 'A desintegração da autoridade imperial na Itália e a transição para a era medieval. Um debate historiográfico clássico de múltiplas teses.', 'debate', '{"title":"A Deposição de Rômulo Augusto","description":"Em setembro de 476 d.C., o líder mercenário germânico Odoacro depôs o jovem usurpador imperial Rômulo Augusto. Odoacro não reivindicou o título imperial, mas enviou as insígnias reais para Constantinopla, declarando-se regente territorial."}'::jsonb, '{"title":"Monocausa Clássica vs. Multicausalidade","description":"No século XVIII, Edward Gibbon propôs que o cristianismo e o enfraquecimento moral minaram as instituições. A historiografia moderna liderada por Peter Heather rejeita a ideia de \"decadência interna pura\", enfatizando o impacto logístico insustentável das migrações de povos bárbaros impulsionados pelos hunos."}'::jsonb, '{"title":"Tese Climática e Pandêmica","description":"Historiadores ambientais propõem que o declínio romano coincidiu com uma fase de instabilidade climática severa (Pequena Idade do Gelo do Ano 536) e surtos epidemiológicos severos que dizimaram a mão de obra camponesa e a arrecadação de impostos."}'::jsonb, '[{"year":"410 d.C.","event":"Roma é saqueada pelos visigodos sob comando de Alarico, abalando o prestígio imperial."},{"year":"476 d.C.","event":"Odoacro assume o controle militar da Itália, extinguindo a linhagem oficial de imperadores ocidentais."},{"year":"541 d.C.","event":"A Peste de Justiniano assola o Mediterrâneo, inviabilizando tentativas persistentes de reconquista."}]'::jsonb, '[{"name":"Rômulo Augusto","role":"Último Imperador Ocidental","bio":"Adolescente entronizado pelo pai que serviu como figura decorativa no desfecho da corte de Ravena."},{"name":"Odoacro","role":"Rei dos Hérulos e General","bio":"Oficial militar germânico que destituiu a autoridade fantoche romana e governou sob vassalagem de Bizâncio."}]'::jsonb, '[{"id":"src-rom-1","title":"The Fall of the Roman Empire: A New History","author":"Peter Heather","year":2005,"type":"book","details":"Capítulo VII"},{"id":"src-rom-2","title":"The Fate of Rome: Climate, Disease, and the End of an Empire","author":"Kyle Harper","year":2017,"type":"book","details":"Parte III, pág. 120-165"},{"id":"src-rom-3","title":"History of the Decline and Fall of the Roman Empire","author":"Edward Gibbon","year":1776,"type":"book","details":"Edição Crítica de 1994"}]'::jsonb, 'published', true),
('reiartur', 'História', 'Idade Média', 'A Historicidade do Rei Artur', 'Idade das Trevas Britânica (Século VI)', 'A busca por vestígios materiais e contemporâneos do lendário líder guerreiro da Távola Redonda. Lenda vs. Realidade Arqueológica.', 'hypothesis', '{"title":"Silêncio Documental Contemporâneo","description":"Não existe qualquer menção a um líder chamado \"Artur\" nas crônicas e tratados britânicos autênticos sobreviventes do século VI, tais como o \"De Excidio et Conquestu Britanniae\" escrito pelo monge Gildas."}'::jsonb, '{"title":"Construção Mítica de Identidade","description":"A maioria dos medievalistas contemporâneos interpreta Artur não como um homem real singular, mas como um amálgama literário — uma figura mítica composta para simbolizar a brava resistência militar dos bretões romano-celtas contra a invasão anglo-saxã."}'::jsonb, '{"title":"O General Riothamus","description":"Pesquisadores como Geoffrey Ashe propõem a hipótese de que o modelo real que inspirou as lendas arturianas teria sido Riothamus, um chefe militar bretão-romano de comprovada atividade na Gália em meados de 470 d.C."}'::jsonb, '[{"year":"516 d.C.","event":"Batalha do Monte Badon, onde guerreiros britões impõem séria derrota tática aos saxões."},{"year":"830 d.C.","event":"A crônica \"Historia Brittonum\" registra formalmente a primeira menção de Artur como general britânico."},{"year":"1136 d.C.","event":"Geoffrey de Monmouth publica sua crônica fictícia, fundando os mitos medievais cavaleirescos."}]'::jsonb, '[{"name":"Gildas Sapiens","role":"Historiador e Monge","bio":"Único cronista britânico sobrevivente do século VI; descreveu as batalhas saxãs mas nunca citou o nome de Artur."},{"name":"Geoffrey de Monmouth","role":"Clérigo e Escritor","bio":"Autor galês medieval cujos manuscritos altamente ficcionalizados deram origem ao mito do rei lendário."}]'::jsonb, '[{"id":"src-art-1","title":"The Discovery of King Arthur","author":"Geoffrey Ashe","year":1985,"type":"book","details":"Cap. II, pág. 45-70"},{"id":"src-art-2","title":"Historia Brittonum","author":"Atribuído a Nênio","year":830,"type":"document","details":"Seção 56 (Códice Harleiano)"},{"id":"src-art-3","title":"Arthurian Literature in the Middle Ages","author":"Roger Sherman Loomis","year":1959,"type":"book","details":"Capítulo I"}]'::jsonb, 'published', true),
('grecia-classica', 'História', 'Antiguidade', 'O Florescimento da Democracia e Filosofia em Atenas (c. 500 a.C.)', 'Antiguidade Clássica (c. 500 a.C.)', 'As reformas democráticas de Clístenes e a consolidação do pensamento filosófico e das artes cênicas na Atenas clássica.', 'high', '{"title":"As Reformas de Clístenes (508 a.C.)","description":"Clístenes reorganizou a população de Atenas em dez tribos baseadas em distritos geográficos (demos) em vez de linhagens familiares, fundando a Eclésia e o Conselho dos 500 (Bulé), estabelecendo a isonomia (igualdade perante a lei) documentada em inscrições de pedra."}'::jsonb, '{"title":"O Caráter de Classe da Democracia Ateniense","description":"Historiadores políticos debatem as limitações estruturais da democracia grega. Enquanto os liberais clássicos a celebravam como liberdade pura, críticos contemporâneos demonstram que ela dependia diretamente da escravidão de massa de prisioneiros estrangeiros e da exclusão total das mulheres da esfera política."}'::jsonb, '{"title":"A Influência Egípcia na Filosofia Pré-Socrática","description":"Embora a filosofia seja descrita tradicionalmente como um \"milagre grego\" autônomo, hipóteses revisionistas sugerem forte herança de conhecimentos geométricos e cosmológicos adquiridos por Tales e Pitágoras em viagens aos templos do Baixo Egito."}'::jsonb, '[{"year":"508 a.C.","event":"Clístenes assume o poder e institui a reorganização política democrática de Atenas."},{"year":"490 a.C.","event":"Batalha de Maratona; forças atenienses derrotam a invasão persa de Dario I, salvaguardando a polis."},{"year":"461 a.C.","event":"Início da Era de Péricles; financiamento estatal de teatros, templos no Acrópole e assembleias populares."}]'::jsonb, '[{"name":"Clístenes","role":"Pai da Democracia","bio":"Aristocrata reformador que quebrou o poder dos clãs tradicionais atenientes e introduziu o sufrágio geográfico."},{"name":"Sexto Empírico","role":"Historiador e Filósofo","bio":"Registrou compilações de debates céticos e das correntes metodológicas que definiam as discussões na ágora."}]'::jsonb, '[{"id":"src-gre-1","title":"A Constituição dos Atenienses","author":"Atribuído a Aristóteles","year":-320,"type":"document","details":"Seções 20-22, Papiros de Londres"},{"id":"src-gre-2","title":"The Ancient Greeks: An Introduction","author":"John V. A. Fine","year":1983,"type":"book","details":"Capítulo 9"}]'::jsonb, 'published', true),
('revolucao-francesa', 'História', 'Idade Moderna', 'A Revolução Francesa e a Queda da Bastilha (1789)', 'Idade Moderna (1789)', 'O levante popular de 14 de julho de 1789 em Paris que desmantelou o absolutismo Bourbon e promulgou a Declaração dos Direitos do Homem.', 'high', '{"title":"A Tomada da Bastilha","description":"Em 14 de julho de 1789, uma multidão armada cercou e tomou a prisão-fortaleza da Bastilha, buscando pólvora e libertando prisioneiros simbólicos. Os relatórios oficiais do governador de Launay e os diários reais de Luís XVI registram o colapso imediato da autoridade real na capital."}'::jsonb, '{"title":"A Tese Revisionista de François Furet","description":"Divergindo da visão marxista clássica (uma revolução burguesa linear), François Furet e historiadores revisionistas argumentam que 1789 foi um colapso democrático onde a política discursiva e a retórica de soberania popular substituíram os conflitos de classe estruturais de curto prazo."}'::jsonb, '{"title":"O Impacto Climático e a Erupção do Laki","description":"Pesquisadores de paleoclima levantam a hipótese de que a erupção do vulcão Laki na Islândia em 1783 causou perturbações atmosféricas globais, provocando invernos rigorosos e quebras de safra sucessivas na França, catalisando a fome extrema que motivou a revolta camponesa."}'::jsonb, '[{"year":"1789","event":"Reunião dos Estados Gerais; o Terceiro Estado se autoproclama Assembleia Nacional."},{"year":"1789","event":"Queda da Bastilha em 14 de julho; promulgação da Declaração dos Direitos do Homem em agosto."},{"year":"1793","event":"Execução do rei Luís XVI e início do período do Terror jacobino liderado por Robespierre."}]'::jsonb, '[{"name":"Luís XVI","role":"Rei de França","bio":"Monarca absolutista deposto cuja indecisão política e crise fiscal culminaram no colapso do Antigo Regime."},{"name":"Maximilien Robespierre","role":"Líder Jacobino","bio":"Advogado e político radical que personificou a fase mais violenta e virtuosa da Revolução Francesa."}]'::jsonb, '[{"id":"src-rev-1","title":"Pensar a Revolução Francesa","author":"François Furet","year":1978,"type":"book","details":"Edição Gallimard, Páginas 45-80"},{"id":"src-rev-2","title":"The French Revolution: A History","author":"Thomas Carlyle","year":1837,"type":"book","details":"Volume I, Cap. III"}]'::jsonb, 'published', true),
('pouso-lua', 'História', 'Idade Moderna', 'A Apollo 11 e o Pouso Lunar da Humanidade (1969)', 'Idade Contemporânea (1969)', 'A alunissagem histórica do Módulo Lunar Eagle na Lua, consolidando o apogeu tecnológico da corrida espacial durante a Guerra Fria.', 'high', '{"title":"A Alunissagem no Mar da Tranquilidade","description":"Em 20 de julho de 1969, Neil Armstrong e Buzz Aldrin pousaram o módulo lunar \"Eagle\" na Lua. A missão foi transmitida ao vivo para 600 milhões de telespectadores e é documentada por mais de 400 kg de amostras de rocha lunar coletadas, registros de rádio da NASA e refletores laser deixados na superfície."}'::jsonb, '{"title":"A Corrida Espacial como Substituto de Guerra","description":"Historiadores de relações internacionais interpretam o programa Apollo não puramente como aventura científica, mas como uma guerra de propaganda substituta crucial entre as duas superpotências nucleares (EUA e URSS) para demonstrar superioridade ideológica."}'::jsonb, '{"title":"Teorias de Conspiração de Fraude Lunar","description":"Apesar de refutadas de forma absoluta por evidências físicas, científicas e historiográficas, hipóteses marginais sugerem que o pouso foi filmado em estúdio de cinema pelo diretor Stanley Kubrick a mando do governo americano."}'::jsonb, '[{"year":"1961","event":"O presidente John F. Kennedy declara a meta de enviar um homem à Lua antes do fim da década."},{"year":"1969","event":"Lançamento do Saturno V em 16 de julho; pouso lunar e caminhada histórica em 20 de julho."},{"year":"1972","event":"A missão Apollo 17 encerra o programa de exploração lunar tripulado da NASA."}]'::jsonb, '[{"name":"Neil Armstrong","role":"Comandante da Apollo 11","bio":"Primeiro ser humano a caminhar na Lua, eternizado pela frase \"um pequeno passo para um homem, um salto gigante para a humanidade\"."},{"name":"Wernher von Braun","role":"Diretor Técnico da NASA","bio":"Pioneiro da engenharia de foguetes alemã, projetista chefe do colossal foguete lançador Saturno V."}]'::jsonb, '[{"id":"src-lua-1","title":"First Man: The Life of Neil A. Armstrong","author":"James R. Hansen","year":2005,"type":"book","details":"Capítulo 18, Simon & Schuster"},{"id":"src-lua-2","title":"Apollo 11 Mission Report","author":"NASA Science Directorate","year":1969,"type":"document","details":"Documento Técnico MSC-00171"}]'::jsonb, 'published', true),
('hamurabi', 'História', 'Antiguidade', 'O Código de Hamurabi (c. 1750 a.C.)', 'Antiguidade Oriental (c. 1750 a.C.)', 'Codificação de 282 leis em acádio cuneiforme gravadas na Estela de Diorita. Causa: Unificação jurídica do Império Babilônico. Mecanismo: Fixação pública e inalterável do direito escrito. Impacto: Princípio da Lei do Talion ("olho por olho") e regulamentação hierárquica. Relevância ENEM: Transição do direito costumeiro para a norma estatal escrita e diferenciação de penas por classe social.', 'high', '{"title":"A Estela de Diorita Negra e a Inscrição Cuneiforme","description":"A estela de 2,25m descoberta em Susa (1901) contém 282 artigos em cuneiforme acádio. No topo, o rei Hamurabi é retratado recebendo as leis diretamente do deus Shamash. O texto regula contratos agrícolas, propriedade, casamento e penas corporais rigorosas."}'::jsonb, '{"title":"Hierarquia Social e a Lei do Talion","description":"O código aplicava penas desiguais conforme o estamento (awilum/livres, mushkenum/dependentes e wardum/escravos). Historiadores como Marc Van De Mieroop explicam que a Lei do Talion visava coibir vinganças privadas desproporcionais, monopolizando a violência no Estado."}'::jsonb, '{"title":"Norma Aplicada vs. Monumento de Propaganda Régia","description":"Assiriólogos debatem se a estela era aplicada estritamente nos tribunais cotidianos ou se funcionava primariamente como um monumento de legitimação política para demonstrar que Hamurabi era o \"rei justo\"."}'::jsonb, '[{"year":"1792 a.C.","event":"Hamurabi ascende ao trono do Império Paleobabilônico."},{"year":"1750 a.C.","event":"Promulgação e erigimento público da Estela de Diorita no templo de Marduk."},{"year":"1150 a.C.","event":"Saque de Babilônia pelos elamitas; a estela é levada como troféu para Susa."},{"year":"1901 d.C.","event":"Descoberta da estela por arqueólogos franceses e envio ao Museu do Louvre."}]'::jsonb, '[{"name":"Hamurabi","role":"Rei da Babilônia (1792–1750 a.C.)","bio":"Unificador da Mesopotâmia responsável por compilar o famoso código legal escrito."},{"name":"Shamash","role":"Deus da Justiça e do Sol","bio":"Divindade babilonia representada concedendo os símbolos de autoridade a Hamurabi."},{"name":"Marc Van De Mieroop","role":"Assiriólogo e Historiador","bio":"Autor de biografias fundamentais sobre Hamurabi e o direito paleobabilônico."}]'::jsonb, '[{"id":"src-ham-1","title":"Estela de Diorita do Código de Hamurabi (Louvre AO 10237)","author":"Escribas de Hamurabi","year":-1750,"type":"archaeological","details":"282 artigos em cuneiforme acádio"},{"id":"src-ham-2","title":"King Hammurabi of Babylon: A Biography","author":"Marc Van De Mieroop","year":2005,"type":"book","details":"Blackwell Publishing, Cap. 5"}]'::jsonb, 'published', true),
('islamismo', 'História', 'Idade Média', 'O Surgimento do Islamismo e a Expansão Árabe (622 d.C.)', 'Alta Idade Média (622 d.C.)', 'A unificação tribal da Arábia pela fé monoteísta a partir da Hégira (622 d.C.) e a formação do Califado. Causa: Fragmentação política no deserto arábico. Mecanismo: O Alcorão, a noção de Umma e a expansão sobre os impérios Bizantino e Sassânida. Impacto: Preservação e ampliação da ciência clássica e rota comercial do Atlântico à Índia. Relevância ENEM: Sincretismo cultural medieval, revolução científica islâmica e o legado do Al-Andalus.', 'high', '{"title":"A Hégira de 622 d.C. e o Estado de Medina","description":"Em 622 d.C., perseguições em Meca forçaram Maomé a migrar para Medina (Hégira), marco inicial do calendário islâmico. Em Medina, a Carta de Medina estabeleceu a primeira constituição monoteísta, unificando clãs rivais sob uma nova ordem social."}'::jsonb, '{"title":"A Tese Pirenne e a Reconfiguração do Mediterrâneo","description":"Henri Pirenne defendeu que a expansão árabe rompeu o comércio no Mediterrâneo, forçando a Europa ocidental a voltar-se para o interior continental e consolidar o feudalismo (\"Sem Maomé, Carlos Magno não teria existido\")."}'::jsonb, '{"title":"Vácuo Geopolítico no Oriente Próximo","description":"Historiadores militares apontam que as rápidas conquistas muçulmanas foram facilitadas pelo esgotamento humano e financeiro de séculos de guerras devastadoras entre Bizâncio e o Império Sassânida."}'::jsonb, '[{"year":"610 d.C.","event":"Primeira revelação profética de Maomé na caverna de Hira."},{"year":"622 d.C.","event":"A Hégira: migração de Meca para Medina; ano zero do calendário islâmico."},{"year":"632–661 d.C.","event":"Califado Ortodoxo: expansão sobre a Síria, Egito, Palestina e Pérsia."},{"year":"711 d.C.","event":"Invasão da Península Ibérica e fundação do Al-Andalus."}]'::jsonb, '[{"name":"Profeta Maomé","role":"Fundador do Islamismo","bio":"Líder religioso e político que unificou a Península Arábica sob o monoteísmo."},{"name":"Califa Omar","role":"Segundo Califa Ortodoxo","bio":"Arquiteto da expansão territorial sobre Jerusalém, Alexandria e a Pérsia."},{"name":"Henri Pirenne","role":"Historiador Belga","bio":"Autor da famosa Tese Pirenne sobre o impacto islâmico no nascimento da Europa medieval."}]'::jsonb, '[{"id":"src-isl-1","title":"Pergaminhos do Alcorão de Birmingham","author":"Anônimo","year":645,"type":"archaeological","details":"Manuscrito em pergaminho datado por C-14"},{"id":"src-isl-2","title":"Mahomet et Charlemagne","author":"Henri Pirenne","year":1937,"type":"book","details":"Edição Albin Michel"}]'::jsonb, 'published', true),
('constantinopla', 'História', 'Idade Média', 'A Queda de Constantinopla (1453 d.C.)', 'Fim da Idade Média (1453 d.C.)', 'A tomada da capital bizantina pelas forças de Mehmet II após 53 dias de cerco com artilharia pesada. Causa: Declínio territorial bizantino e expansão otomana. Mecanismo: Bombardas de bronze e transporte de navios por terra para o Chifre de Ouro. Impacto: Fim do Império Romano do Oriente, bloqueio comercial terrestre para a Ásia e fuga de sábios gregos acelerando o Renascimento. Relevância ENEM: Transição da Idade Média para a Idade Moderna e estímulo às Grandes Navegações.', 'high', '{"title":"O Cerco de 1453 e a Ruptura das Muralhas Teodosianas","description":"Em 29 de maio de 1453, Mehmet II rompeu as muralhas de Constantinopla com o uso da bombarda gigante de Urbano e estratégias audaciosas. O imperador Constantino XI morreu em combate, marcando o fim definitivo do Império Bizantino."}'::jsonb, '{"title":"A Revolução da Artilharia de Pólvora","description":"Historiadores militares analisam a queda como o triunfo da artilharia sobre as fortificações medievais de pedra, encerrando a era da cavalaria e forçando o desenvolvimento da arquitetura militar moderna."}'::jsonb, '{"title":"Reavaliação do Bloqueio de Especiarias","description":"Historiadores econômicos demonstram que os otomanos não proibiram o comércio cristão, mas elevaram tarifas alfandegárias, estimulando a busca ibérica por rotas marítimas diretas sem intermediários."}'::jsonb, '[{"year":"1453 (Abril)","event":"Início do cerco otomano com 80.000 homens e bombardeio de artilharia."},{"year":"1453 (Maio 22)","event":"Mehmet II transporta 70 galés por terra contornando Gálata até o Chifre de Ouro."},{"year":"1453 (Maio 29)","event":"Conquista da cidade e transformação da Basílica de Santa Sofia em mesquita."}]'::jsonb, '[{"name":"Mehmet II","role":"Sultão Otomano (O Conquistador)","bio":"Estrategista genial que conquistou Constantinopla aos 21 anos."},{"name":"Constantino XI","role":"Último Imperador Bizantino","bio":"Soberano que liderou a defesa desesperada e tombou nas muralhas."},{"name":"Steven Runciman","role":"Historiador Britânico","bio":"Autor da obra clássica sobre a queda de Constantinopla."}]'::jsonb, '[{"id":"src-con-1","title":"Diário do Cerco de Constantinopla","author":"Niccolò Barbaro","year":1453,"type":"document","details":"Relato de testemunha ocular veneziana"},{"id":"src-con-2","title":"The Fall of Constantinople 1453","author":"Steven Runciman","year":1965,"type":"book","details":"Cambridge University Press"}]'::jsonb, 'published', true),
('reforma-protestante', 'História', 'Idade Moderna', 'A Reforma Protestante e Lutero (1517 d.C.)', 'Idade Moderna (1517 d.C.)', 'A afixação das 95 Teses por Martinho Lutero em Wittenberg contra a venda de indulgências. Causa: Abusos do clero e crise moral católica. Mecanismo: Difusão pela imprensa de Gutenberg, salvação pela fé e sola scriptura. Impacto: Quebra da unidade cristã no Ocidente, guerras de religião e fortalecimento do vernáculo. Relevância ENEM: Relação entre religião, burguesia, imprensa e modernidade política.', 'high', '{"title":"As 95 Teses e a Imprensa de Gutenberg","description":"Em 31 de outubro de 1517, Lutero denunciou o comércio das indulgências pelo dominicano Tetzel. A recém-inventada imprensa de Gutenberg multiplicou o texto em alemão por toda a Europa em semanas."}'::jsonb, '{"title":"A Ética Protestante e o Capitalismo (Max Weber)","description":"Max Weber articulou que o calvinismo e o puritanismo protestante, ao valorizarem o trabalho disciplinado e a poupança como sinais de salvação, impulsionaram a mentalidade capitalista moderna."}'::jsonb, '{"title":"Interesses Financeiros dos Príncipes Alemães","description":"Historiadores sociais apontam que a Reforma prosperou no Sacro Império porque os príncipes viram a oportunidade de confiscar terras da Igreja e cessar os impostos enviados a Roma."}'::jsonb, '[{"year":"1517","event":"Afixação das 95 Teses na porta da Igreja do Castelo de Wittenberg."},{"year":"1521","event":"Dieta de Worms; Lutero recusa se retratar e é excomungado por Leão X."},{"year":"1534","event":"Lutero publica a tradução completa da Bíblia para o alemão vernacular."},{"year":"1555","event":"Paz de Augsburgo estabelece a liberdade religiosa para príncipes alemães."}]'::jsonb, '[{"name":"Martinho Lutero","role":"Teólogo e Monge Reformador","bio":"Iniciador da Reforma Protestante ao contestar as indulgências papais."},{"name":"Leão X","role":"Papa da Igreja Católica","bio":"Pontífice que promoveu as indulgências para financiar a Basílica de São Pedro."},{"name":"Max Weber","role":"Sociólogo Alemão","bio":"Autor da tese que vincula a ética protestante ao surgimento do capitalismo."}]'::jsonb, '[{"id":"src-ref-1","title":"As 95 Teses sobre a Eficácia das Indulgências","author":"Martinho Lutero","year":1517,"type":"document","details":"Texto impresso em Wittenberg"},{"id":"src-ref-2","title":"A Ética Protestante e o Espírito do Capitalismo","author":"Max Weber","year":1905,"type":"book","details":"Edição Crítica"}]'::jsonb, 'published', true),
('revolucao-industrial', 'História', 'Idade Contemporânea', 'A Primeira Revolução Industrial (c. 1760 d.C.)', 'Século XVIII (c. 1760 d.C.)', 'A mecanização da produção têxtil e a máquina a vapor de James Watt na Grã-Bretanha. Causa: Acumulação de capital, cercamentos (Enclosures) e carvão abundante. Mecanismo: Energia a vapor e sistema fabril. Impacto: Surgimento do proletariado, exôdo rural, urbanização desordenada e capitalismo industrial. Relevância ENEM: Ludismo, cartismo, alienação do trabalho (Marx) e problemas ambientais urbanos.', 'high', '{"title":"A Máquina a Vapor e o Êxodo Rural","description":"A máquina a vapor de James Watt (1769) e as leis de cercamento (Enclosure Acts) forçaram camponeses sem terra a migrarem para cidades industriais como Manchester, criando o operariado fabril."}'::jsonb, '{"title":"A Dupla Revolução de Eric Hobsbawm","description":"Eric Hobsbawm definiu a Revolução Industrial britânica juntamente com a Revolução Francesa como a \"Dupla Revolução\" que fundou a sociedade contemporânea ocidental."}'::jsonb, '{"title":"Pioneirismo Britânico e Recursos Coloniais","description":"Debate-se se o pioneirismo inglês ocorreu por patentes e ciência ou pela exploração das matérias-primas e mercados consumidores cativos do seu império colonial."}'::jsonb, '[{"year":"1733","event":"Invenção da lançadeira volante por John Kay."},{"year":"1769","event":"James Watt patenteia a máquina a vapor aprimorada."},{"year":"1811–1816","event":"Movimento Ludista destrói teares mecânicos em protesto contra baixos salários."},{"year":"1838","event":"Publicação da Carta do Povo (Movimento Cartista) exigindo direitos operários."}]'::jsonb, '[{"name":"James Watt","role":"Engenheiro Escocês","bio":"Aprimorou a máquina a vapor, tornando-a a fonte motriz da revolução fabril."},{"name":"Ned Ludd","role":"Líder Operário Mítico","bio":"Símbolo da resistência artesanal contra a mecanização destruidora de empregos."},{"name":"Eric Hobsbawm","role":"Historiador Britânico","bio":"Analista definitivo da industrialização e do desenvolvimento do capitalismo."}]'::jsonb, '[{"id":"src-ind-1","title":"A Era das Revoluções (1789-1848)","author":"Eric Hobsbawm","year":1962,"type":"book","details":"Paz e Terra, Cap. 2"},{"id":"src-ind-2","title":"O Capital","author":"Karl Marx","year":1867,"type":"book","details":"Livro I, Seção IV"}]'::jsonb, 'published', true),
('primeira-guerra-russa', 'História', 'Idade Contemporânea', 'A Primeira Guerra e a Revolução Russa (1914–1917)', 'Início do Século XX (1914–1917)', 'A Grande Guerra imperialista europeia e a revolução bolchevique de 1917. Causa: Imperialismo, alianças militares e colapso ksarista. Mecanismo: Guerra de trincheiras e a tomada do poder pelos soviéticos sob Lênin ("Paz, Pão e Terra"). Impacto: Fim de 4 impérios, criação da URSS e início da disputa ideológica do século XX. Relevância ENEM: Ideologias contemporâneas, fim das autocracias e origem do bloco socialista.', 'high', '{"title":"Atentado de Sarajevo e a Revolução de Outubro","description":"O assassinato de Francisco Ferdinando em 1914 deflagrou a guerra. O esgotamento russo levou à queda do Czar em fevereiro de 1917 e à tomada do Palácio de Inverno pelos Bolcheviques de Lênin em outubro."}'::jsonb, '{"title":"O Breve Século XX de Hobsbawm","description":"Hobsbawm delimita o \"Breve Século XX\" (1914-1991) iniciando na Primeira Guerra e na Revolução Russa, que inauguraram a era do confronto ideológico global."}'::jsonb, '{"title":"Contingência de Guerra vs. Inevitabilidade Social","description":"Historiadores discutem se a vitória bolchevique decorreu das contradições agrárias estruturais ou da oportunidade única gerada pelo colapso militar na Grande Guerra."}'::jsonb, '[{"year":"1914","event":"Atentado em Sarajevo e início da Primeira Guerra Mundial."},{"year":"1917 (Fev)","event":"Revolução de Fevereiro deposita o Czar Nicolau II."},{"year":"1917 (Out)","event":"Revolução de Outubro: Bolcheviques assumem o poder."},{"year":"1918","event":"Tratado de Brest-Litovsk retira a Rússia do conflito."}]'::jsonb, '[{"name":"Vladimir Lênin","role":"Líder Bolchevique","bio":"Chefe teórico e político da Revolução Russa e primeiro líder soviético."},{"name":"Czar Nicolau II","role":"Último Czar da Rússia","bio":"Monarca autocrata cuja má gestão da guerra levou ao colapso do império."},{"name":"Leon Trotsky","role":"Comandante do Exército Vermelho","bio":"Estrategista crucial na consolidação do poder soviético."}]'::jsonb, '[{"id":"src-1gm-1","title":"Dez Dias que Abalaram o Mundo","author":"John Reed","year":1919,"type":"book","details":"Relato jornalístico de testemunha ocular"},{"id":"src-1gm-2","title":"A Era dos Extremos","author":"Eric Hobsbawm","year":1994,"type":"book","details":"Companhia das Letras, Cap. 1-2"}]'::jsonb, 'published', true),
('segunda-guerra-holocausto', 'História', 'Idade Contemporânea', 'A Segunda Guerra Mundial e o Holocausto (1939–1945)', 'Meados do Século XX (1939–1945)', 'O conflito global entre Aliados e Eixo nazi-fascista e o extermínio de 6 milhões de judeus. Causa: Expansionismo nazista e ideologia do "espaço vital". Mecanismo: Blitzkrieg, campos industriais de morte e bomba atômica. Impacto: Criação da ONU, Declaração dos Direitos Humanos e início da Guerra Fria. Relevância ENEM: Totalitarismo, direitos humanos, memória histórica e nova ordem geopolítica.', 'high', '{"title":"Invasão da Polônia e os Campos de Extermínio","description":"A invasão da Polônia em 1939 deu início à guerra. Na Conferência de Wannsee (1942), o nazismo sistematizou a \"Solução Final\", executando milhões em campos de extermínio como Auschwitz-Birkenau."}'::jsonb, '{"title":"A Banalidade do Mal e a Modernidade Industrial","description":"Hannah Arendt definiu a \"banalidade do mal\" ao analisar Eichmann. Zygmunt Bauman demonstrou que o Holocausto utilizou a própria racionalidade industrial e burocrática moderna."}'::jsonb, '{"title":"Grau de Culpabilidade da População Civil","description":"Debate-se até que ponto cidadãos alemães comuns tinham conhecimento ativo do genocídio ou se viviam sob coerção e propaganda massiva do regime."}'::jsonb, '[{"year":"1939","event":"Alemanha invade a Polônia; início da Segunda Guerra Mundial."},{"year":"1941","event":"Ataque a Pearl Harbor e início da operação industrial da Solução Final."},{"year":"1942–1943","event":"Batalha de Stalingrado: virada soviética contra o exército nazista."},{"year":"1945","event":"Fim da guerra na Europa e bombas atômicas em Hiroshima e Nagasaki."}]'::jsonb, '[{"name":"Adolf Hitler","role":"Ditador da Alemanha Nazista","bio":"Arquiteto do expansionismo fascista e do genocídio do Holocausto."},{"name":"Hannah Arendt","role":"Filósofa Política","bio":"Autora de análises sobre o totalitarismo e a banalidade do mal."},{"name":"Winston Churchill","role":"Primeiro-Ministro Britânico","bio":"Líder da resistência aliada ocidental contra o nazismo."}]'::jsonb, '[{"id":"src-2gm-1","title":"Eichmann em Jerusalém","author":"Hannah Arendt","year":1963,"type":"book","details":"Viking Press"},{"id":"src-2gm-2","title":"Modernidade e Holocausto","author":"Zygmunt Bauman","year":1989,"type":"book","details":"Jorge Zahar Editor"}]'::jsonb, 'published', true),
('mitologia-nordica', 'Mitologia', 'Mitologias', 'Mitologia Nórdica: Asgard e o Ragnarök', 'Era Viking (Século VIII–XI d.C.)', 'A cosmologia germânico-escandinava da arvore Yggdrasil, os Nove Reinos e o crepúsculo cíclico do Ragnarök. Causa: Sacralização dos rigorosos ciclos da natureza e valorização do guerreiro. Mecanismo: Tradição oral das eddas e escrita islandesa. Impacto: Influência duradoura na cultura, na linguagem e na literatura de fantasia ocidental. Relevância ENEM: Análise de mitos de criação e percepção do tempo cíclico.', 'mythological', '{"title":"A Cosmogonia da Yggdrasil e as Eddas","description":"Os nórdicos representavam o cosmos sustentado pela fresno Yggdrasil, unindo nove mundos (Asgard, Midgard, Helheim). Os manuscritos mediais islandeses (Edda em Verso e Edda em Prosa) são as fontes primárias preservadas."}'::jsonb, '{"title":"A Mortabilidade dos Deuses e o Ragnarök","description":"Diferente dos deuses imortais mediterrâneos, Odin, Thor e Loki estão sujeitos ao fado (Urðr). O Ragnarök representa a batalha final catastrófica necessária para a renovação de um novo mundo."}'::jsonb, '{"title":"Influência do Cristianismo nas Escritas Islandesas","description":"Linguistas apontam que a visão de um mundo renovado após o Ragnarök na Völuspá reflete influências cristãs trazidas pelos copistas islandeses do século XIII."}'::jsonb, '[{"year":"c. 800 d.C.","event":"Auge da Era Viking e transmissão oral das canções mitológicas."},{"year":"c. 1220 d.C.","event":"Snorri Sturluson escreve a Edda em Prosa na Islândia."},{"year":"1270 d.C.","event":"Compilação do Codex Regius contendo a Edda em Verso."}]'::jsonb, '[{"name":"Odin","role":"Pai de Todos","bio":"Deus supremo da sabedoria, magia das runas, poesia e guerra."},{"name":"Thor","role":"Deus do Trovão","bio":"Protetor dos homens e de Midgard, armado com o martelo Mjölnir."},{"name":"Snorri Sturluson","role":"Historiador Islandês","bio":"Autor responsável por registrar por escrito as tradições nórdicas."}]'::jsonb, '[{"id":"src-nor-1","title":"Codex Regius da Edda Poética","author":"Monges Islandeses","year":1270,"type":"myth","details":"Manuscrito na Islândia"},{"id":"src-nor-2","title":"Myth and Religion of the North","author":"Gabriel Turville-Petre","year":1964,"type":"book","details":"Weidenfeld & Nicolson"}]'::jsonb, 'published', true),
('mitologia-mesoamericana', 'Mitologia', 'Mitologias', 'Mitologias Precolombianas: Popol Vuh e Quetzalcóatl', 'Período Pré-Colombiano (c. 2000 a.C. – 1532 d.C.)', 'Cosmogonias e cultos agrícolas das civilizações Maia, Asteca e Inca. Causa: Sacralização do milho, Sol e chuva vitais à agricultura. Mecanismo: Rituais de reciprocidade com o divino e textos sagrados como o Popol Vuh. Impacto: Arquitetura monumental de pirâmides e preservação da identidade indígena. Relevância ENEM: Diversidade das matrizes ameríndias e cosmovisão pré-colombiana.', 'mythological', '{"title":"O Homem de Milho no Popol Vuh","description":"O Popol Vuh maia narra a criação da humanidade a partir do milho amarelo e branco, após tentativas frustradas com lama e madeira, simbolizando a sacralidade da agricultura."}'::jsonb, '{"title":"Reciprocidade Sagrada e Sacrifícios","description":"Miguel León-Portilla explica que para os astecas, os deuses (como Quetzalcóatl e Huitzilopochtli) necessitavam de rituais e oferendas para manter a ordem cósmica e o movimento do Sol."}'::jsonb, '{"title":"Desmistificação do Mito de Quetzalcóatl","description":"Historiadores modernos contestam a lenda de que Moctezuma considerou Cortés como a reencarnação de Quetzalcóatl, demonstrando ser uma construção narrativa espanhola pós-conquista."}'::jsonb, '[{"year":"2000 a.C.","event":"Início do cultivo sagrado do milho na Mesoamérica."},{"year":"300–900 d.C.","event":"Período Clássico Maia e desenvolvimento do calendário solar."},{"year":"1325 d.C.","event":"Fundação de Tenochtitlán pelos astecas no Vale do México."},{"year":"1550 d.C.","event":"Redação em alfabeto latino do Popol Vuh na Guatemala."}]'::jsonb, '[{"name":"Quetzalcóatl","role":"Serpente Emplumada","bio":"Divindade da sabedoria, do vento e do conhecimento na Mesoamérica."},{"name":"Gêmeos Heróis","role":"Hunahpú e Ixbalanqué","bio":"Protagonistas do Popol Vuh que venceram os deuses da morte em Xibalbá."},{"name":"Miguel León-Portilla","role":"Antropólogo Mexicano","bio":"Tradutor e defensor da filosofia e literatura Nahuatl."}]'::jsonb, '[{"id":"src-mes-1","title":"Manuscrito do Popol Vuh","author":"Autores Maias K''iche''","year":1550,"type":"myth","details":"Biblioteca Newberry de Chicago"},{"id":"src-mes-2","title":"A Filosofia Nahuatl","author":"Miguel León-Portilla","year":1956,"type":"book","details":"UNAM México"}]'::jsonb, 'published', true),
('brasil-colonial', 'História do Brasil', 'História do Brasil', 'A Chegada dos Portugueses e o Brasil Colonial (1500)', 'Século XVI–XVIII (1500)', 'A chegada da esquadra de Cabral e a colonização agroexportadora do açúcar. Causa: Expansão marítima mercantilista portuguesa. Mecanismo: Capitanias, Governo-Geral e escravização de indígenas e africanos. Impacto: Estruturação da sociedade patriarcal, latifundiária e escravista brasileira. Relevância ENEM: Carta de Caminha, resistência indígena/quilombola e economia açucareira.', 'high', '{"title":"A Carta de Caminha e a Economia do Açúcar","description":"Em 22 de abril de 1500, Cabral aportou na Bahia. A Carta de Pero Vaz de Caminha registrou o primeiro contato. A partir de 1530, a instalação dos engenhos de açúcar consolidou a colonização mercantilista."}'::jsonb, '{"title":"Sentido da Colonização (Caio Prado Jr.)","description":"Caio Prado Júnior definiu o \"sentido da colonização\" como a exploração predatória de gêneros tropicais voltada exclusivamente para o enriquecimento das metrópoles europeias."}'::jsonb, '{"title":"Intencionalidade do Descobrimento","description":"Historiadores navais defendem que a frota de Cabral não chegou ao Brasil por acaso, mas por uma missão sigilosa de D. João II para garantir as terras do Tratado de Tordesilhas."}'::jsonb, '[{"year":"1500 (Abril 22)","event":"Chegada de Pedro Álvares Cabral a Porto Seguro (BA)."},{"year":"1532","event":"Fundação da Vila de São Vicente e primeiro engenho de açúcar."},{"year":"1549","event":"Instalação do Governo-Geral com Tomé de Sousa em Salvador."},{"year":"1595","event":"Formação inicial do Quilombo dos Palmares na Serra da Barriga."}]'::jsonb, '[{"name":"Pedro Álvares Cabral","role":"Navegador Português","bio":"Capitão-mor da esquadra que oficializou a posse portuguesa do Brasil em 1500."},{"name":"Pero Vaz de Caminha","role":"Escrivão da Esquadra","bio":"Autor da famosa carta relatando as terras e os nativos a D. Manuel I."},{"name":"Caio Prado Júnior","role":"Historiador Brasileiro","bio":"Autor do clássico \"Formação do Brasil Contemporâneo\"."}]'::jsonb, '[{"id":"src-bra-1","title":"Carta do Achamento do Brasil","author":"Pero Vaz de Caminha","year":1500,"type":"document","details":"Torre do Tombo, Lisboa"},{"id":"src-bra-2","title":"Formação do Brasil Contemporâneo","author":"Caio Prado Júnior","year":1942,"type":"book","details":"Editora Brasiliense"}]'::jsonb, 'published', true),
('brasil-imperio', 'História do Brasil', 'História do Brasil', 'A Independência e o Império do Brasil (1822–1889)', 'Século XIX (1822–1889)', 'A independência conduzida pela elite escravista, mantendo a monarquia, a unidade territorial e o Segundo Reinado de D. Pedro II. Causa: Vinda da Família Real (1808) e recolonização pelas Cortes de Lisboa. Mecanismo: Monarquia constitucional, Poder Moderador e economia cafeeira. Impacto: Abolição da escravidão (1888) e Proclamação da República (1889). Relevância ENEM: Constituição de 1824, Poder Moderador, Guerra do Paraguai e abolicionismo.', 'high', '{"title":"O 7 de Setembro e o Poder Moderador","description":"Proclamada em 1822 por D. Pedro I, a Independência preservou o regime monárquico. A Constituição de 1824 criou o Poder Moderador, conferindo autoridade pessoal ao imperador sobre os demais poderes."}'::jsonb, '{"title":"A Construção da Ordem e o Medo da Fragmentação","description":"José Murilo de Carvalho demonstra que a elite brasileira optou pela monarquia para evitar a fragmentação territorial e revoltas populares (\"medo do haitianismo\") que ameaçassem a escravidão."}'::jsonb, '{"title":"Resistência Negra e a Conquista da Abolição","description":"Historiadores negros (como Eduardo Silva) provam que a Lei Áurea de 1888 não foi dádiva imperial, mas resultado de insurreições nas senzalas, aquilombamento e pressão do movimento abolicionista."}'::jsonb, '[{"year":"1808","event":"Transferência da Corte portuguesa para o Rio de Janeiro e abertura dos portos."},{"year":"1822","event":"Grito do Ipiranga e aclamação de D. Pedro I como Imperador."},{"year":"1840","event":"Golpe da Maioridade: início do Segundo Reinado de D. Pedro II."},{"year":"1888","event":"Assinatura da Lei Áurea extinguindo a escravidão no Brasil."},{"year":"1889","event":"Proclamação da República pelo Marechal Deodoro da Fonseca."}]'::jsonb, '[{"name":"D. Pedro II","role":"Imperador do Brasil","bio":"Governou o Brasil de 1840 a 1889, símbolo de estabilidade política e patrono das artes."},{"name":"Luís Gama","role":"Líder Abolicionista e Jurista","bio":"Ex-escravizado autodidata que libertou centenas de cativos nos tribunais paulistas."},{"name":"José Murilo de Carvalho","role":"Historiador do Império","bio":"Referência acadêmica na análise das elites e da cidadania no Brasil Imperial."}]'::jsonb, '[{"id":"src-imp-1","title":"Constituição do Império do Brasil","author":"Conselho de Estado","year":1824,"type":"document","details":"Arquivo Nacional do Rio de Janeiro"},{"id":"src-imp-2","title":"A Construção da Ordem","author":"José Murilo de Carvalho","year":1980,"type":"book","details":"Editora Campus"}]'::jsonb, 'published', true),
('era-vargas', 'História do Brasil', 'História do Brasil', 'A Era Vargas e o Estado Novo (1930–1945)', 'Século XX (1930–1945)', 'A Revolução de 1930, a industrialização estatal, a criação da CLT e a ditadura do Estado Novo. Causa: Crise de 1929 e fim da hegemonia paulista-mineira. Mecanismo: Centralização política, leis trabalhistas tuteladas e propaganda oficial do DIP. Impacto: Nascimento da CLT, da CSN e consolidação da identidade nacional urbana. Relevância ENEM: Trabalhismo, propaganda do DIP, industrialização e cidadania regulada.', 'high', '{"title":"A CLT (1943) e o Aparelho de Propaganda do DIP","description":"Em 1943, Vargas outorgou a CLT, garantindo direitos sociais. Por outro lado, o DIP censurava a oposição e construía o mito do \"Pai dos Pobres\" através da \"A Hora do Brasil\"."}'::jsonb, '{"title":"A Cidadania Regulada (Wanderley Guilherme)","description":"Wanderley Guilherme dos Santos explicou que os direitos trabalhistas na Era Vargas eram concedidos aos cidadãos em função da sua profissão reconhecida em carteira assinada vinculada ao Estado."}'::jsonb, '{"title":"A Farsa do Plano Cohen","description":"O pretexto utilizado para dar o golpe do Estado Novo em 1937 foi o \"Plano Cohen\", um documento falso forjado por militares para simular uma iminente ameaça comunista no Brasil."}'::jsonb, '[{"year":"1930","event":"Revolução de 1930 depõe Washington Luís e conduz Vargas ao poder."},{"year":"1932","event":"Revolução Constitucionalista em São Paulo pela constitucionalização."},{"year":"1937","event":"Golpe do Estado Novo e outorga da Constituição de 1937 (\"Polaca\")."},{"year":"1943","event":"Promulgação da Consolidação das Leis do Trabalho (CLT)."},{"year":"1945","event":"Deposição militar de Vargas e encerramento do Estado Novo."}]'::jsonb, '[{"name":"Getúlio Vargas","role":"Presidente e Ditador","bio":"Figura central da história brasileira do século XX, pai do trabalhismo e da industrialização."},{"name":"Wanderley Guilherme dos Santos","role":"Cientista Político","bio":"Autor do conceito de cidadania regulada para analisar o modelo varguista."},{"name":"Lourival Fontes","role":"Diretor do DIP","bio":"Idealizador da máquina de censura e propaganda pública do Estado Novo."}]'::jsonb, '[{"id":"src-var-1","title":"Consolidação das Leis do Trabalho (CLT)","author":"Governo Getúlio Vargas","year":1943,"type":"document","details":"Diário Oficial da União"},{"id":"src-var-2","title":"Cidadania e Justiça","author":"Wanderley Guilherme dos Santos","year":1979,"type":"book","details":"Editora Campus"}]'::jsonb, 'published', true),
('ditadura-militar-brasil', 'História do Brasil', 'História do Brasil', 'A Ditadura Militar e a Redemocratização (1964–1985)', 'Século XX (1964–1985)', 'O regime civil-militar instaurado em 1964, marcado pelo AI-5, censura, represão política e o processo de abertura até a Constituição de 1988. Causa: Guerra Fria, reformas de base de Jango e medo do comunismo nas elites. Mecanismo: Atos Institucionais, Milagre Econômico e campanha Diretas Já. Impacto: Violações de direitos humanos, endividamento externo e promulgação da Carta Cidadã de 1988. Relevância ENEM: AI-5, censura artística, Diretas Já e a Constituição de 1988.', 'high', '{"title":"O AI-5 de 1968 e o Relatório da Comissão da Verdade","description":"Em dezembro de 1968, o AI-5 fechou o Congresso, suspendeu o habeas corpus e oficializou a censura prévia. A Comissão Nacional da Verdade (2014) comprovou o assassinato e desaparecimento de 434 opositores do regime."}'::jsonb, '{"title":"A Caracterização Civil-Militar da Ditadura","description":"Historiadores (como Daniel Aarão Reis) destacam que o regime teve apoio civil ativo de empresários, veículos de imprensa e setores conservadores, viabilizado temporariamente pelo \"Milagre Econômico\"."}'::jsonb, '{"title":"Apoio Logístico dos EUA na Operação Brother Sam","description":"Documentos sigilosos comprovam que o governo americano mobilizou uma frota naval para apoiar o golpe de 1964 caso houvesse resistência armada fidedigna de tropas leais a João Goulart."}'::jsonb, '[{"year":"1964 (Abril 1)","event":"Golpe civil-militar depõe o presidente João Goulart."},{"year":"1968 (Dez 13)","event":"Decretado o AI-5, dando início ao período mais repressivo da ditadura."},{"year":"1979","event":"Sancionada a Lei de Anistia no governo do general João Figueiredo."},{"year":"1984","event":"Campanha das \"Diretas Já\" reúne milhões de brasileiros pelo voto direto."},{"year":"1988","event":"Promulgação da Constituição Cidadã restaurando a democracia."}]'::jsonb, '[{"name":"João Goulart (Jango)","role":"Presidente Deposto","bio":"Presidente constitucional derrubado pelo golpe civil-militar de 1964."},{"name":"Vladimir Herzog","role":"Jornalista","bio":"Assassinado pelo regime em 1975 no DOI-CODI, sua morte mobilizou a resistência civil."},{"name":"Daniel Aarão Reis","role":"Historiador","bio":"Especialista em ditadura militar, censura e movimentos de resistência política."}]'::jsonb, '[{"id":"src-dit-1","title":"Relatório Final da Comissão Nacional da Verdade","author":"Governo Federal do Brasil","year":2014,"type":"document","details":"3 Volumes, Brasília"},{"id":"src-dit-2","title":"A Ditadura Escancarada","author":"Elio Gaspari","year":2002,"type":"book","details":"Companhia das Letras"}]'::jsonb, 'published', true),
('guerras-medicas', 'História', 'Antiguidade', 'As Guerras Médicas / Persas (499 – 449 a.C.)', 'Antiguidade Clássica (499–449 a.C.)', 'Grécia (Atenas e Esparta) vs. Império Persa (Batalhas de Maratona, Termópilas e Salamina). Fundamental para entender a hegemonia grega, a formação da Liga de Delos e a preservação da autonomia cultural e política das polis.', 'high', '{"title":"As Invasões Persas e a Resistência Grega","description":"Conflito secular travado entre as cidades-estado gregas e o Império Persa Aquêmenida de Dário I e Xerxes I na Bacia do Egeu.","causaImediata":"A Revolta das cidades gregas da Jônia (como Mileto) na Ásia Menor contra o domínio do Império Persa em 499 a.C., recebendo apoio militar e marítimo enviado por Atenas.","desenvolvimento":"Duas grandes invasões persas. Primeira Invasão (490 a.C.): Batalha de Maratona, onde a falange hoplita ateniense derrotou as tropas de Dário I. Segunda Invasão (480 a.C.): Heróica resistência dos 300 espartanos de Leônidas nas Termópilas, seguida pela vitória naval decisiva de Atenas em Salamina (comandada por Temístocles) e a batalha terrestre final de Plateia (479 a.C.).","consequencias":"Recuo definitivo dos persas da Europa, preservação da autonomia cultural e política grega, hegemonia de Atenas no Egeu (Auge do Século de Péricles) e fundação da Liga de Delos."}'::jsonb, '{"title":"O Mito da Liberdade Ocidental vs. Despotismo Oriental","description":"Heródoto construiu a narrativa fundacional da historiografia ao opor a liberdade da polis grega à servidão autocrática persa, conceito reanalisado pela historiografia contemporânea."}'::jsonb, '{"title":"União Grega Contingente","description":"Historiadores demonstram que a aliança entre Atenas e Esparta foi estritamente emergencial e temporária, desmoronando logo em seguida na devastadora Guerra do Peloponeso."}'::jsonb, '[{"year":"499 a.C.","event":"Início da Revolta Jônica apoiada por Atenas contra Dário I."},{"year":"490 a.C.","event":"Primeira Invasão Persa; vitória ateniense na Batalha de Maratona."},{"year":"480 a.C.","event":"Segunda Invasão Persa; Batalha das Termópilas e vitória naval grega em Salamina."},{"year":"478 a.C.","event":"Fundação da Liga de Delos sob liderança de Atenas."},{"year":"449 a.C.","event":"Assinatura da Paz de Calias, encerrando oficialmente as hostilidades."}]'::jsonb, '[{"name":"Leônidas I","role":"Rei de Esparta","bio":"Comandante heróico dos 300 espartanos que tombaram no desfiladeiro das Termópilas."},{"name":"Temístocles","role":"Estrategista Ateniense","bio":"Idealizador do poder naval de Atenas e arquiteto da vitória tática na Batalha de Salamina."},{"name":"Heródoto","role":"Pai da História","bio":"Cronista grego que registrou a narrativa primária das Guerras Médicas em sua obra *Histórias*."}]'::jsonb, '[{"id":"src-med-1","title":"Histórias (Historiai)","author":"Heródoto","year":-440,"type":"document","details":"Livros VI a IX"},{"id":"src-med-2","title":"The Persian Wars","author":"Charles Hignett","year":1963,"type":"book","details":"Oxford University Press"}]'::jsonb, 'published', true),
('guerras-punicas', 'História', 'Antiguidade', 'As Guerras Púnicas (264 – 146 a.C.)', 'Antiguidade Clássica Romana (264–146 a.C.)', 'Roma vs. Cartago (Aníbal e seus elefantes). O marco fundamental que destruiu a potência fenícia e transformou Roma na maior potência militar e econômica do Mediterrâneo (Mare Nostrum).', 'high', '{"title":"A Disputa do Mediterrâneo Ocidental","description":"Série de três guerras travadas entre Roma e a república marítima de Cartago pelo controle do comércio mediterrâneo.","causaImediata":"Disputa pelo controle estratégico da ilha da Sicília e das rotas comerciais mercantis do Mediterrâneo Ocidental.","desenvolvimento":"Primeira Guerra (264-241 a.C.): Roma constrói sua frota naval e conquista a Sicília. Segunda Guerra (218-201 a.C.): O general cartaginês Aníbal Barca atravessa os Alpes com elefantes de guerra e impõe severas derrotas a Roma (Cannas), sendo vencido por Cipião o Africano em Zama (202 a.C.). Terceira Guerra (149-146 a.C.): Cerco brutal e aniquilação física total de Cartago.","consequencias":"Destruição total de Cartago, transformação do Mediterrâneo em Mare Nostrum romano, expansão acelerada do latifúndio escravista e transição da República para o imperialismo."}'::jsonb, '{"title":"A Virada Imperialista da República Romana","description":"Polybius analisou como a vitória sobre Cartago forneceu a infraestrutura militar e os recursos financeiros que converteram Roma de potência regional em império universal."}'::jsonb, '{"title":"Destruição Salina de Cartago: Mito ou Fato","description":"Arqueólogos modernos apontam que a lenda de que os romanos teriam jogado sal na terra de Cartago para torná-la infértil é uma construção literária do século XIX."}'::jsonb, '[{"year":"264 a.C.","event":"Início da Primeira Guerra Púnica pela disputa da Sicília."},{"year":"218 a.C.","event":"Aníbal inicia a travessia lendária dos Alpes com exército e elefantes."},{"year":"216 a.C.","event":"Batalha de Cannas; maior massacre tático sofrido pelo exército romano."},{"year":"202 a.C.","event":"Batalha de Zama; Cipião o Africano derrota Aníbal no norte da África."},{"year":"146 a.C.","event":"Destruição completa de Cartago e criação da Província Romana da África."}]'::jsonb, '[{"name":"Aníbal Barca","role":"General Cartaginês","bio":"Genial estrategista militar que levou a guerra até os portões de Roma."},{"name":"Cipião o Africano","role":"General e Cônsul Romano","bio":"Vencedor de Aníbal na Batalha de Zama e mestre das táticas militares romanas."},{"name":"Políbio","role":"Historiador Grego","bio":"Cronista de guerra que testemunhou a queda de Cartago e escreveu as *Histórias*."}]'::jsonb, '[{"id":"src-pun-1","title":"Histórias (Historiké Syntaxis)","author":"Políbio","year":-150,"type":"document","details":"Livros III e XV"},{"id":"src-pun-2","title":"A History of Rome to A.D. 565","author":"Arthur Boak","year":1965,"type":"book","details":"Cap. VII"}]'::jsonb, 'published', true),
('cruzadas', 'História', 'Idade Média', 'As Cruzadas (1095 – 1291 d.C.)', 'Idade Média (1095–1291 d.C.)', 'O choque entre a Cristandade Ocidental e o Mundo Islâmico pelo controle de Jerusalém e da Terra Santa, motivando profundas transformações comerciais, sociais e culturais.', 'high', '{"title":"Movimento Militar-Religioso no Levante","description":"Expedições armadas convocadas pelo Papado que mobilizaram cavaleiros, reis e camponeses em direção ao Oriente Próximo.","causaImediata":"O apelo do imperador bizantino Aleixo I e a convocação do Papa Urbano II no Concílio de Clermont (1095) prometendo a remissão dos pecados aos que libertassem Jerusalém dos turcos seljúcidas.","desenvolvimento":"Primeira Cruzada (1096-1099): Tomada sangrenta de Jerusalém e criação dos Reinos Cruzados. Segunda e Terceira Cruzada: Duelo entre o sultão Saladino (que reconquistou Jerusalém em 1187) e Ricardo Coração de Leão. Quarta Cruzada (1202-1204): Desviada pelos interesses de Veneza, resultou no saque de Constantinopla.","consequencias":"Reabertura das rotas mercantis no Mediterrâneo (renascimento urbano e comercial), enfraquecimento dos senhores feudais e fortalecimento do poder monárquico."}'::jsonb, '{"title":"Expansão Feudal vs. Guerra Santa","description":"Historiadores econômicos analisam as Cruzadas como válvula de escape para o excedente populacional e a busca de terras pela nobreza desprovida de feudos na Europa."}'::jsonb, '{"title":"Convivência Pragmática no Levante","description":"Registros de cronistas árabes como Usama ibn Munqidh mostram que, entre as guerras, havia intensa convivência comercial, médica e cultural entre cruzados e muçulmanos."}'::jsonb, '[{"year":"1095","event":"Papa Urbano II convoca o Concílio de Clermont e decreta a Primeira Cruzada."},{"year":"1099","event":"Conquista de Jerusalém pelos cruzados e fundação do Reino de Jerusalém."},{"year":"1187","event":"Saladino reconquista Jerusalém na Batalha de Hattin."},{"year":"1204","event":"Quarta Cruzada saqueia a capital cristã de Constantinopla."},{"year":"1291","event":"Queda de São João d''Acre, encerrando a presença cruzada na Terra Santa."}]'::jsonb, '[{"name":"Papa Urbano II","role":"Pontífice Católico","bio":"Iniciador do movimento cruzado no discurso histórico de Clermont."},{"name":"Saladino (Salah ad-Din)","role":"Sultão do Egito e Síria","bio":"Líder muçulmano respeitado por sua cavalheirismo e reconquistador de Jerusalém."},{"name":"Ricardo Coração de Leão","role":"Rei da Inglaterra","bio":"Comandante da Terceira Cruzada e principal oponente militar de Saladino."}]'::jsonb, '[{"id":"src-cru-1","title":"Gesta Francorum et aliorum Hierosolimitanorum","author":"Anônimo","year":1101,"type":"document","details":"Relato de testemunha da 1ª Cruzada"},{"id":"src-cru-2","title":"As Cruzadas Vistas pelos Árabes","author":"Amin Maalouf","year":1983,"type":"book","details":"Editora Brasiliense"}]'::jsonb, 'published', true),
('guerra-cem-anos', 'História', 'Idade Média', 'A Guerra dos Cem Anos (1337 – 1453 d.C.)', 'Fim da Idade Média (1337–1453 d.C.)', 'França vs. Inglaterra (Joana D''Arc). O fim do sistema feudal de cavalaria, o nascimento dos exércitos permanentes e a transição para as monarquias nacionais consolidadas.', 'high', '{"title":"O Secular Conflito Dinástico e Territorial","description":"Conflito prolongado travado em solo francês entre a dinastia dos Valois (França) e a dinastia dos Plantageneta (Inglaterra).","causaImediata":"Disputa pela sucessão do trono francês após a morte de Carlos IV em 1328 e o controle da rica região mercantil de Flandres.","desenvolvimento":"Fase de vitórias inglesas impulsionadas pelos arqueiros na Batalha de Crécy (1346) e Azincourt (1415). Fase de virada francesa (1429): Liderança mística e militar de Joana D''Arc rompendo o Cerco de Orléans e coroando Carlos VII, culminando na vitória francesa final em Castillon (1453).","consequencias":"Expulsão dos ingleses da França, consolidação do sentimento nacionalista e centralização das monarquias absolutas na França e Inglaterra."}'::jsonb, '{"title":"O Nascimento da Identidade Nacional Moderna","description":"Historiadores franceses e britânicos analisam o conflito como o catalisador que separou a identidade cultural de ambos os reinos, extinguindo o mundo feudal fragmentado."}'::jsonb, '{"title":"O Papel da Artilharia de Pólvora na Vitória Francesa","description":"Pesquisadores militares demonstram que foram os canhões franceses desenvolvidos pelos irmãos Bureau, e não apenas o fervor de Joana D''Arc, que decidiram as batalhas finais de Castillon."}'::jsonb, '[{"year":"1337","event":"Eduardo III da Inglaterra declara guerra à França."},{"year":"1346","event":"Batalha de Crécy; demonstração do poder destruidor do arco longo inglês."},{"year":"1415","event":"Batalha de Azincourt; vitória esmagadora de Henrique V da Inglaterra."},{"year":"1429","event":"Joana D''Arc liberta a cidade de Orléans e transforma o rumo da guerra."},{"year":"1453","event":"Batalha de Castillon; vitória francesa decisiva e fim do conflito."}]'::jsonb, '[{"name":"Joana D''Arc","role":"Heroína e Padroeira da França","bio":"Jovem camponesa cujas visões e coragem lideraram a reconquista do território francês."},{"name":"Henrique V","role":"Rei da Inglaterra","bio":"Monarca guerreiro responsável pela vitória memorável na Batalha de Azincourt."},{"name":"Carlos VII","role":"Rei da França","bio":"Monarca coroado em Reims graças ao apoio de Joana D''Arc que unificou a França."}]'::jsonb, '[{"id":"src-100-1","title":"Chroniques de Froissart","author":"Jean Froissart","year":1400,"type":"document","details":"Manuscrito iluminado"},{"id":"src-100-2","title":"The Hundred Years War","author":"Robin Neillands","year":1990,"type":"book","details":"Routledge"}]'::jsonb, 'published', true),
('guerras-napoleonicas', 'História', 'Idade Moderna', 'As Guerras Napoleônicas (1803 – 1815 d.C.)', 'Idade Contemporânea (1803–1815 d.C.)', 'O expansionismo francês sob Napoleão Bonaparte, o Bloqueio Continental, a transferência da Família Real Portuguesa para o Brasil em 1808 e a redefinição do mapa político no Congresso de Viena.', 'high', '{"title":"A Hegemonia Napoleônica e a Reconstrução Européia","description":"Série de conflitos entre o Primeiro Império Francês de Napoleão e coligações de potências absolutistas financiadas pela Grã-Bretanha.","causaImediata":"Ambição de Napoleão em estender a hegemonia da Revolução Francesa e destruir o monopólio comercial britânico.","desenvolvimento":"Vitórias brilhantes na Europa continental (Austerlitz em 1805). O Bloqueio Continental (1806) força a fuga da Família Real Portuguesa para o Brasil (1808). A desastrosa Invasão da Rússia (1812) dizima a Grande Armée, culminando na derrota final na Batalha de Waterloo (1815).","consequencias":"Congresso de Viena (1815) restaurando as monarquias europeias, difusão do ideário liberal e aceleração das independências na América Latina."}'::jsonb, '{"title":"Modernização Institucional via Conquista","description":"Historiadores do direito destacam que o Código Napoleônico abolindo o feudalismo foi implantado em todos os territórios ocupados, fundando as bases do Estado moderno europeu."}'::jsonb, '{"title":"O Papel do Inverno Russo vs. Tática da Terra Arrasada","description":"Análises logísticas mostram que as febres e a escassez de suprimentos provocadas pela terra arrasada russa causaram mais baixas a Napoleão do que o rigor do inverno."}'::jsonb, '[{"year":"1804","event":"Napoleão Bonaparte coroa-se Imperador dos Franceses na Catedral de Notre-Dame."},{"year":"1805","event":"Derrota naval em Trafalgar para a Grã-Bretanha e vitória brilhante em Austerlitz."},{"year":"1806","event":"Decreto de Berlim instituindo o Bloqueio Continental contra a Inglaterra."},{"year":"1808","event":"Chegada da Família Real Portuguesa ao Rio de Janeiro após a invasão de Portugal."},{"year":"1815","event":"Batalha de Waterloo e início do Congresso de Viena."}]'::jsonb, '[{"name":"Napoleão Bonaparte","role":"Imperador dos Franceses","bio":"Estrategista militar lendário e reformador do direito moderno ocidental."},{"name":"Duque de Wellington","role":"General Britânico","bio":"Comandante das forças aliadas que venceu Napoleão na Batalha de Waterloo."},{"name":"D. João VI","role":"Príncipe Regente de Portugal","bio":"Monarca que transferiu a corte portuguesa para o Rio de Janeiro em 1808."}]'::jsonb, '[{"id":"src-nap-1","title":"The Napoleonic Wars: A Very Short Introduction","author":"Mike Rapport","year":2013,"type":"book","details":"Oxford University Press"},{"id":"src-nap-2","title":"1808","author":"Laurentino Gomes","year":2007,"type":"book","details":"Editora Planeta"}]'::jsonb, 'published', true),
('guerra-civil-espanhola', 'História', 'Idade Contemporânea', 'A Guerra Civil Espanhola (1936 – 1939 d.C.)', 'Século XX (1936–1939 d.C.)', 'O ensaio geral da Segunda Guerra Mundial. O golpe fascista do General Franco contra a Segunda República Espanhola, com testes de armas nazistas (Guernica) e a participação das Brigadas Internacionais.', 'high', '{"title":"Fascismo vs. Democracia no Solo Ibérico","description":"Conflito violento que dividiu a Espanha entre 1936 e 1939, antecipando os blocos e táticas da II Guerra.","causaImediata":"O golpe de Estado promovido em julho de 1936 por generais ultraconservadores contra o governo eleito da Segunda República (Frente Popular).","desenvolvimento":"Os Nacionalistas de Franco receberam apoio maciço de tropas, tanques e aviação de Hitler e Mussolini (Legião Condor nazista bombardeia Guernica). Os Republicanos lutaram apoiados pelas Brigadas Internacionais e pela URSS.","consequencias":"Vitória de Franco e instalação da ditadura franquista (1939-1975), devastação da Espanha e consolidação das táticas de guerra da Alemanha Nazista."}'::jsonb, '{"title":"Laboratório de Guerra e Ideologia","description":"Hugh Thomas analisa a guerra como a primeira grande batalha física entre o fascismo europeu ascendente e o bloco democrático/socialista."}'::jsonb, '{"title":"O Impacto da \"Não-Intervenção\" Ocidental","description":"Historiadores demonstram que a política de \"Não-Intervenção\" mantida por França e Grã-Bretanha selou o destino da democracia espanhola, isolando os republicanos."}'::jsonb, '[{"year":"1936 (Julho)","event":"Golpe militar liderado pelo General Francisco Franco no Marrocos espanhol."},{"year":"1937 (Abril)","event":"Bombardeio nazista da cidade basca de Guernica pela Legião Condor."},{"year":"1938","event":"Batalha do Ebro; maior e mais sangrenta batalha do conflito."},{"year":"1939 (Março)","event":"Queda de Madri, vitória franquista e início da ditadura."}]'::jsonb, '[{"name":"General Francisco Franco","role":"Caudilho da Espanha","bio":"Líder dos rebeldes fascistas que governou a Espanha autoritariamente até 1975."},{"name":"Pablo Picasso","role":"Pintor Espanhol","bio":"Criador do painel monumental *Guernica*, denúncia universal dos horrores da guerra."},{"name":"Dolores Ibárruri (La Pasionaria)","role":"Líder Republicana","bio":"Oradora inflamada famosa pelo bordão antifascista \"¡No pasarán!\"."}]'::jsonb, '[{"id":"src-esp-1","title":"The Spanish Civil War","author":"Hugh Thomas","year":1961,"type":"book","details":"Harper & Row"},{"id":"src-esp-2","title":"Homage to Catalonia","author":"George Orwell","year":1938,"type":"book","details":"Relato autbiográfico de voluntário"}]'::jsonb, 'published', true),
('guerra-fria-conflitos', 'História', 'Idade Contemporânea', 'A Guerra Fria e os Conflitos Indiretos (1947 – 1991 d.C.)', 'Século XX (1947–1991 d.C.)', 'A Ordem Bipolar global (EUA vs. URSS). Disputas por procuração na Coreia, Vietnã, Crise dos Mísseis em Cuba, Corrida Espacial, ditaduras latino-americanas e a queda do Bloco Soviético em 1991.', 'high', '{"title":"Tensão Geopolítica Bipolar sem Confronto Direto","description":"Antagonismo ideológico, econômico e militar entre o capitalismo liderado por Washington e o socialismo liderado por Moscou.","causaImediata":"A divisão da Europa em zonas de influência após a Segunda Guerra Mundial e a Doutrina Truman de contenção do comunismo.","desenvolvimento":"Conflitos indiretos: Guerra da Coreia (1950-1953), Crise dos Mísseis em Cuba (1962), Guerra do Vietnã (1955-1975), Corrida Espacial e Armamentista (MAD).","consequencias":"Subvenção de regimes autoritários no Terceiro Mundo, colapso econômico da URSS, queda do Muro de Berlim (1989) e dissolução da União Soviética (1991)."}'::jsonb, '{"title":"Paz Quente no Terceiro Mundo","description":"John Lewis Gaddis ressalta que embora a Europa tenha vivido a \"Longa Paz\", a Guerra Fria foi extremamente quente e mortal na Ásia, África e América Latina."}'::jsonb, '{"title":"A Inevitabilidade da Falência Soviética","description":"Economistas políticos apontam que a corrida armamentista travada por Reagan nos anos 80 acelerou a falência estrutural do modelo de economia planificada soviético."}'::jsonb, '[{"year":"1947","event":"Anúncio da Doutrina Truman e criação do Plano Marshall."},{"year":"1950–1953","event":"Guerra da Coreia; consolidação da divisão da península no Paralelo 38°."},{"year":"1962","event":"Crise dos Mísseis em Cuba; apogeu do risco nuclear entre Kennedy e Khrushchev."},{"year":"1975","event":"Fim da Guerra do Vietnã e unificação comunista do país."},{"year":"1989–1991","event":"Queda do Muro de Berlim e dissolução da União Soviética."}]'::jsonb, '[{"name":"John F. Kennedy","role":"Presidente dos EUA","bio":"Líder americano durante a dramática Crise dos Mísseis de Cuba e o Programa Apollo."},{"name":"Nikita Khrushchev","role":"Líder da União Soviética","bio":"Primeiro-secretário do PCUS que promoveu a desestalinização e a Crise de Cuba."},{"name":"Mikhail Gorbachev","role":"Último Líder da URSS","bio":"Promotor da *Glasnost* e *Perestroika* que conduziram ao fim negociado da Guerra Fria."}]'::jsonb, '[{"id":"src-fri-1","title":"The Cold War: A New History","author":"John Lewis Gaddis","year":2005,"type":"book","details":"Penguin Books"},{"id":"src-fri-2","title":"Diplomacia","author":"Henry Kissinger","year":1994,"type":"book","details":"Editora Francisco Alves"}]'::jsonb, 'published', true),
('guerra-canudos', 'História do Brasil', 'História do Brasil', 'A Guerra de Canudos (1896 – 1897)', 'República Velha (1896–1897)', 'O massacre da comunidade messiânica de Antônio Conselheiro no sertão da Bahia. A resistência heroica dos sertanejos contra o Exército da recém-fundada República, eternizada por Euclides da Cunha.', 'high', '{"title":"O Arraial de Belo Monte e o Massacre Sertanejo","description":"Levante social e comunitário no sertão baiano que reuniu 25.000 pessoas marginalizadas pela miséria e seca.","causaImediata":"Inconformismo de Antônio Conselheiro com a cobrança de novos impostos pela República e litígio comercial de madeira em Juazeiro.","desenvolvimento":"Formação do Arraial comunitário de Canudos. Três expedições militares estaduais e federais foram vergonhosamente derrotadas pela guerrilha sertaneja na caatinga. A quarta expedição nacional usou artilharia pesada e milhares de soldados para exterminar o arraial.","consequencias":"Destruição total de Canudos, massacre de 25.000 sertanejos e denúncia da profunda exclusão social do Brasil em *Os Sertões*."}'::jsonb, '{"title":"O Choque entre Dois Brasís","description":"Euclides da Cunha interpretou Canudos como o trágico desencontro entre o litoral urbano ocidentalizado e o sertão arcaico esquecido."}'::jsonb, '{"title":"Autonomia Comunitária vs. Ameaça Monarquista","description":"Historiadores modernos provam que Canudos não era uma conspiração monarquista financiada pelo exterior, mas um movimento de sobrevivência e fé camponesa autônoma."}'::jsonb, '[{"year":"1893","event":"Antônio Conselheiro e seus seguidores fixam-se na fazenda abandonada de Canudos."},{"year":"1896 (Nov)","event":"Primeira expedição militar é derrotada pelos sertanejos em Uauá."},{"year":"1897 (Março)","event":"Derrota e morte do Coronel Moreira César na terceira expedição."},{"year":"1897 (Outubro)","event":"Queda final do Arraial de Canudos e morte dos últimos defensores."}]'::jsonb, '[{"name":"Antônio Conselheiro","role":"Líder Messiânico","bio":"Peregrino que fundou Belo Monte (Canudos) como refúgio comunitário para os desvalidos."},{"name":"Euclides da Cunha","role":"Engenheiro e Jornalista","bio":"Coordenou a cobertura de guerra para O Estado de S. Paulo e escreveu *Os Sertões*."},{"name":"Coronel Moreira César","role":"Comandante Militar","bio":"Famoso pela truculência no Rio de Janeiro, foi morto na desastrosa 3ª expedição."}]'::jsonb, '[{"id":"src-can-1","title":"Os Sertões","author":"Euclides da Cunha","year":1902,"type":"book","details":"Edição Crítica de Walnice Nogueira Galvão"},{"id":"src-can-2","title":"A Guerra do Fim do Mundo","author":"Mario Vargas Llosa","year":1981,"type":"book","details":"Romance histórico fundamentado"}]'::jsonb, 'published', true),
('guerra-do-paraguai', 'História do Brasil', 'História do Brasil', 'A Guerra do Paraguai / Tríplice Aliança (1864 – 1870)', 'Brasil Império (1864–1870)', 'O maior conflito militar da história da América do Sul. Tríplice Aliança (Brasil, Argentina e Uruguai) vs. Paraguai de Solano López. Riachuelo, Tuiuti, Caxias e as consequências sociopolíticas para o Império.', 'high', '{"title":"Conflito Continental na Bacia do Rio da Prata","description":"Guerra total travada entre a Tríplice Aliança e o Paraguai pela navegação dos rios e hegemonia regional.","causaImediata":"A intervenção armada do Brasil no Uruguai (1864) e o apresamento do vapor brasileiro *Marquês de Olinda* por ordem de Solano López.","desenvolvimento":"Vitória naval do Brasil em Riachuelo (1865) fecha os rios ao Paraguai. Sangrenta Batalha de Tuiuti (1866). Comando de Caxias na \"Dezembrada\" (1868) e ocupação de Assunção (1869), terminando na caçada a López em Cerro Corá (1870).","consequencias":"Devastação demográfica e econômica do Paraguai, fortalecimento político do Exército Brasileiro (abolicionismo/republicanismo) e endividamento imperial."}'::jsonb, '{"title":"Imperialismo Inglês vs. Questões Platinas Locais","description":"A historiografia revisou a antiga tese da \"mão invisível inglesa\", provando que o conflito nasceu das disputas internas de fronteira e consolidação dos Estados platinos."}'::jsonb, '{"title":"Contraditório Papel dos Voluntários da Pátria Escravizados","description":"A promessa de alforria enviou milhares de negros escravizados para a guerra, cuja atuação destacada tornou insustentável a manutenção da escravidão no retorno."}'::jsonb, '[{"year":"1864 (Dezembro)","event":"Paraguai aprisiona o navio *Marquês de Olinda* e invade o Mato Grosso."},{"year":"1865 (Junho)","event":"Batalha Naval do Riachuelo; destruição da esquadra paraguaia pela Marinha Imperial."},{"year":"1866 (Maio)","event":"Batalha de Tuiuti; maior e mais mortífera batalha em solo sul-americano."},{"year":"1868 (Dezembro)","event":"Ofensiva de Caxias na \"Dezembrada\" (Avaí, Lomas Valentas e Ytororó)."},{"year":"1870 (Março)","event":"Batalha de Cerro Corá e morte de Francisco Solano López."}]'::jsonb, '[{"name":"Duque de Caxias","role":"Patrono do Exército Brasileiro","bio":"Comandante supremo que reorganizou as tropas brasileiras e venceu a fase decisiva."},{"name":"Francisco Solano López","role":"Presidente do Paraguai","bio":"Ditador paraguaio que conduziu o país à guerra total e recusou a rendição até a morte."},{"name":"Almirante Barroso","role":"Comandante da Marinha Imperial","bio":"Herói da Batalha Naval do Riachuelo com a famosa célebre ordem \"O Brasil espera que cada um cumpra o seu dever\"."}]'::jsonb, '[{"id":"src-par-1","title":"Maldita Guerra: Nova História da Guerra do Paraguai","author":"Francisco Doratioto","year":2002,"type":"book","details":"Companhia das Letras"},{"id":"src-par-2","title":"Diário da Guerra do Paraguai","author":"Alfredo d''Escragnolle Taunay","year":1870,"type":"document","details":"Relato de oficial e escritor"}]'::jsonb, 'published', true),
('feb-segunda-guerra', 'História do Brasil', 'História do Brasil', 'A FEB na Segunda Guerra Mundial (1944 – 1945)', 'Século XX (1944–1945)', 'A participação heroica do Brasil na vitória aliada sobre o nazifascismo. Os 25.000 pracinhas na Frente Italiana, as vitórias em Monte Castello e Fornovo di Taro e a contradição que derrubou o Estado Novo de Vargas.', 'high', '{"title":"A Cobra Vai Fumar na Linha Gótica","description":"O envio da Força Expedicionária Brasileira (FEB) e da FAB para combater as divisões alemãs na Itália.","causaImediata":"O afundamento brutal de navios mercantes brasileiros por submarinos do Eixo no Atlântico Sul em 1942, mobilizando a opinião pública.","desenvolvimento":"Envio de 25.000 pracinhas sob o comando do General Mascarenhas de Moraes. Enfrentando neve rigorosa, venceram as batalhas estratégicas de Monte Castello (fevereiro de 1945) e Castelnuovo, aprisionando uma divisão alemã inteira em Fornovo di Taro.","consequencias":"Glorificação militar do soldado brasileiro e aceleração da queda da ditadura de Getúlio Vargas em 1945 devido à contradição de combater regimes autoritários fora do país."}'::jsonb, '{"title":"Alinhamento Pragmático com Washington","description":"Gerson Moura demonstra que Vargas negociou o envio da FEB e os suprimentos de borracha e quartzo em troca do financiamento americano para a Usina Siderúrgica de Volta Redonda (CSN)."}'::jsonb, '{"title":"A Legendária Origem do Lema \"A Cobra Vai Fumar\"","description":"A expressão popular nasceu da ironia dos céticos que diziam ser \"mais fácil uma cobra fumar cachimbo do que o Brasil entrar na guerra\"."}'::jsonb, '[{"year":"1942 (Agosto)","event":"Vargas declara estado de beligerância contra a Alemanha e Itália após afundamento de navios."},{"year":"1944 (Julho)","event":"Desembarque do primeiro contingente da FEB em Nápoles, Itália."},{"year":"1945 (Fevereiro)","event":"Tomada histórica de Monte Castello pelas tropas brasileiras após meses de cerco."},{"year":"1945 (Abril)","event":"Rendição da 148ª Divisão Alemã em Fornovo di Taro aos pracinhas."}]'::jsonb, '[{"name":"General Mascarenhas de Moraes","role":"Comandante da FEB","bio":"Liderou o contingente brasileiro com brilhantismo e disciplina na Frente Italiana."},{"name":"Capitão Av. Nero Moura","role":"Comandante do 1º Grupo de Caça","bio":"Líder da aviação brasileira (\"Senta a Pua!\") que realizou centenas de missões de ataque."},{"name":"Gerson Moura","role":"Historiador das Relações Internacionais","bio":"Autor de obras fundamentais sobre o alinhamento Brasil-EUA na Segunda Guerra."}]'::jsonb, '[{"id":"src-feb-1","title":"A FEB pelo seu Comandante","author":"Marshal J.B. Mascarenhas de Moraes","year":1947,"type":"document","details":"Editora do Autor"},{"id":"src-feb-2","title":"Suplicantes em Washington: Brasil na Segunda Guerra","author":"Gerson Moura","year":1986,"type":"book","details":"Editora Brasiliense"}]'::jsonb, 'published', true),
('rota-da-seda-imperio-mongol', 'História', 'Idade Média', 'A Rota da Seda e o Império Mongol (c. 130 a.C. – 1206 d.C.)', 'Antiguidade Oriental e Idade Média', 'A teia de redes comerciais da Rota da Seda e sua unificação política sob Genghis Khan no século XIII, fundando o maior império contínuo da história mundial e impulsionando trocas científicas e culturais entre Oriente e Ocidente.', 'high', '{"title":"A Pax Mongolica e a Conexão Eurasiática","description":"Sob o comando de Temüjin (Genghis Khan) a partir de 1206 d.C., os exércitos nômades mongóis unificaram a estepe, conquistaram a China (Dinastia Yuan) e expandiram-se até a Rússia e o Leste Europeu. O sistema de correios imperiais com estações de troca (Yam) permitiu que viajantes como Marco Polo cruzassem a Eurásia em segurança sob a garantia da lei mongol (Yassa)."}'::jsonb, '{"title":"Integração Comercial e Transmissão Tecnológica Global","description":"Historiadores orientais e ocidentais destacam que o Império Mongol não representou apenas saques militares, mas funcionou como o principal catalisador da globalização pré-moderna, transferindo a bússola marítima, a pólvora, o papel e a imprensa móvel de porcelana da China para o mundo islâmico e para a Europa."}'::jsonb, '{"title":"Vetor de Disseminação da Peste Negra","description":"Pesquisadores epidemiológicos e históricos sustentam que a extrema fluidez e rapidez comercial garantida pela Pax Mongolica através das rotas caravaneiras facilitou inadvertidamente a rápida propagação da Peste Negra (Yersinia pestis) dos reservatórios da Ásia Central para o porto de Caffa e para a Europa em 1347."}'::jsonb, '[{"year":"130 a.C.","event":"A Dinastia Han oficializa as rotas caravaneiras da Rota da Seda após as missões de Zhang Qian."},{"year":"1206 d.C.","event":"Kurultai (Assembleia dos Clãs) aclama Temüjin como Genghis Khan, unificando a Mongólia."},{"year":"1271–1295 d.C.","event":"Marco Polo viaja à China e serve na corte do Grão-Khan Kublai Khan."},{"year":"1368 d.C.","event":"A Dinastia Ming derruba os mongóis na China, fragmentando o império em canatos regionais."}]'::jsonb, '[{"name":"Genghis Khan (Temüjin)","role":"Fundador do Império Mongol","bio":"Gênio militar e diplomático que unificou os clãs das estepes e criou o maior império contínuo do planeta."},{"name":"Kublai Khan","role":"Imperador da China e Grão-Khan","bio":"Neto de Genghis Khan que fundou a Dinastia Yuan e construiu a capital Khanbaliq (atual Pequim)."},{"name":"Marco Polo","role":"Mercador e Cronista Veneziano","bio":"Viajante que registrou em \"As Viagens de Marco Polo\" as riquezas e a organização do império mongol."}]'::jsonb, '[{"id":"src-mon-1","title":"A História Secreta dos Mongóis","author":"Anônimo da Corte Mongol","year":1240,"type":"document","details":"Único registro literário mongol contemporâneo preservado"},{"id":"src-mon-2","title":"Genghis Khan and the Making of the Modern World","author":"Jack Weatherford","year":2004,"type":"book","details":"Crown Publishers, Cap. 3-7"}]'::jsonb, 'published', true),
('independencia-eua-1776', 'História', 'Idade Moderna', 'A Independência dos Estados Unidos e o Iluminismo (1776 d.C.)', 'Século XVIII (1776 d.C.)', 'A ruptura colonial das Treze Colônias contra a Coroa Britânica em 1776. Fundada nos princípios iluministas de John Locke e Montesquieu, deu origem à primeira república constitucional e ao modelo democrático representativo moderno.', 'high', '{"title":"A Declaração de Independência de 4 de Julho de 1776","description":"Elaborada por Thomas Jefferson, John Adams e Benjamin Franklin durante o Segundo Congresso Continental na Filadélfia, a declaração rompeu os laços com o Rei Jorge III, afirmando que todos os homens possuem direitos inalienáveis — à vida, liberdade e busca pela felicidade — e que governos derivam seu consentimento dos governados."}'::jsonb, '{"title":"O Efeito Dominó das Revoluções Atlânticas","description":"O historiador Eric Hobsbawm e pesquisadores da \"Era das Revoluções Atlânticas\" apontam a Revolução Americana como o gatilho inicial que desestabilizou o Antigo Regime europeu: inspirou diretamente a Revolução Francesa de 1789, a Revolução Haitiana de 1791 e as independências da América Latina."}'::jsonb, '{"title":"Contradição entre Liberdade Iluminista e Escravidão","description":"Historiadores sociais analisam a profunda contradição fundacional da república americana, na qual autores da declaração de liberdade (como Jefferson e Washington) eram proprietários de centenas de pessoas escravizadas, postergando o debate abolicionista por quase um século."}'::jsonb, '[{"year":"1773","event":"Festa do Chá de Boston (Boston Tea Party) em protesto contra impostos coloniais britânicos."},{"year":"1776 (4 Julho)","event":"Aprovação e publicação oficial da Declaração de Independência na Filadélfia."},{"year":"1781","event":"Batalha de Yorktown; vitória decisiva franco-americana contra as tropas britânicas."},{"year":"1787","event":"Promulgação da Constituição dos Estados Unidos institui o presidencialismo e três poderes."}]'::jsonb, '[{"name":"Thomas Jefferson","role":"Autor da Declaração e 3º Presidente","bio":"Mente intelectual iluminista das Treze Colônias e principal redator da Declaração de Independência."},{"name":"George Washington","role":"Comandante Militar e 1º Presidente","bio":"General que liderou o Exército Continental na guerra e tornou-se o primeiro presidente americano."},{"name":"Benjamin Franklin","role":"Cientista, Diplomata e Político","bio":"Articulador crucial da aliança militar com a França que garantiu recursos para a vitória republicana."}]'::jsonb, '[{"id":"src-eua-1","title":"Declaração de Independência dos Estados Unidos","author":"Thomas Jefferson et al.","year":1776,"type":"document","details":"Original preservado nos Arquivos Nacionais (National Archives, Washington)"},{"id":"src-eua-2","title":"The Ideological Origins of the American Revolution","author":"Bernard Bailyn","year":1967,"type":"book","details":"Harvard University Press, Prêmio Pulitzer"}]'::jsonb, 'published', true),
('restauracao-meiji-japao', 'História', 'Idade Contemporânea', 'A Restauração Meiji e o Fim do Japão Feudal (1868 d.C.)', 'Século XIX (1868 d.C.)', 'A queda do Xogunato Tokugawa e a abolição da ordem feudal dos samurais, dando lugar à rápida industrialização, centralização imperial e ocidentalização tecnológica sob o Imperador Meiji.', 'high', '{"title":"A Queda de Edo e a Lei de Abolição dos Daimyos e Samurais","description":"Em 1868, após a Guerra Boshin entre forças fiéis ao Xogum e partidários imperiais, o Xogum Tokugawa Yoshinobu renunciou. A capital foi transferida de Quioto para Edo (renomeada Tóquio). O novo governo aboliu os domínios feudais (han), proibiu os samurais de carregarem espadas em público e criou um exército nacional de recrutamento obrigatório."}'::jsonb, '{"title":"A Reação ao Imperialismo Ocidental (\"Fukoku Kyohei\")","description":"A historiografia asiática explica que o lema Meiji \"Fukoku Kyohei\" (Enriquecer o País, Fortalecer o Exército) não foi mera cópia do Ocidente, mas uma estratégia defensiva para evitar o destino da China (subjugada na Guerra do Ópio), transformando o Japão em um império autônomo e altamente competitivo."}'::jsonb, '{"title":"O Papel dos Jovens Samurais Baixos","description":"Especialistas em história japonesa demonstram que a revolução não partiu da massa camponesa nem do imperador adolescente, mas de uma elite de samurais de baixa patente dos feudos do sul (Satsuma e Choshu), como Saigo Takamori e Ito Hirobumi."}'::jsonb, '[{"year":"1853","event":"O Comodoro americano Matthew Perry força a abertura dos portos japoneses com os \"Navios Negros\"."},{"year":"1868","event":"Guerra Boshin, restauração formal do Imperador Meiji e proclamação do Juramento de Cinco Artigos."},{"year":"1871–1873","event":"Missão Iwakura percorre EUA e Europa estudando leis, fábricas e o sistema escolar moderno."},{"year":"1889","event":"Promulgação da Constituição Meiji estabelece a Dieta Imperial (parlamento)."}]'::jsonb, '[{"name":"Imperador Meiji (Mutsuhito)","role":"Imperador do Japão (1867–1912)","bio":"Símbolo da renovação nacional sob cujo reinado o Japão transformou-se em potência global."},{"name":"Saigo Takamori","role":"Líder Samurai de Satsuma","bio":"Pai do exército moderno que posteriormente liderou a Rebelião de Satsuma em defesa da honra samurai."},{"name":"Ito Hirobumi","role":"Primeiro-Ministro do Japão","bio":"Arquiteto da Constituição Meiji e da modernização do sistema de governo parlamentar japonês."}]'::jsonb, '[{"id":"src-meiji-1","title":"The Meiji Restoration","author":"W. G. Beasley","year":1972,"type":"book","details":"Stanford University Press"},{"id":"src-meiji-2","title":"Juramento dos Cinco Artigos da Era Meiji","author":"Governo Imperial","year":1868,"type":"document","details":"Decreto Imperial de 6 de abril de 1868"}]'::jsonb, 'published', true),
('guerra-fria-queda-muro-berlim', 'História', 'Idade Contemporânea', 'A Guerra Fria e a Queda do Muro de Berlim (1947 – 1989 d.C.)', 'Segunda Metade do Século XX (1947–1989 d.C.)', 'A disputa ideológica, econômica e militar entre o bloco capitalista (EUA) e o bloco socialista (URSS). Marcada pela corrida armamentista nuclear e pela icônica Queda do Muro de Berlim em 1989, antecipando a dissolução da URSS.', 'high', '{"title":"A Divisão Ideológica e a Noite de 9 de Novembro de 1989","description":"Construído em 1961 pela Alemanha Oriental (RDA) para conter a fuga de cidadãos para Berlim Ocidental, o Muro de Berlim permaneceu por 28 anos como o maior símbolo físico da Cortina de Ferro. Em 9 de novembro de 1989, sob intensa pressão popular e um anúncio incorreto de abertura de fronteiras, milhares de berlinenses de ambos os lados derrubaram o muro com picaretas e marretas."}'::jsonb, '{"title":"As Reformas de Gorbachev e o Fim da Bipolaridade","description":"Historiadores analisam que a queda não ocorreu por agressão militar da OTAN, mas pela falência econômica do modelo soviético e pelas políticas de transparência (Glasnost) e reestruturação (Perestroika) de Mikhail Gorbachev, que recusou enviar tanques para conter os protestos no Leste Europeu."}'::jsonb, '{"title":"A Tese do \"Fim da História\" de Francis Fukuyama","description":"Após a queda do muro e o colapso soviético em 1991, o cientista político Francis Fukuyama lançou a hipótese de que a humanidade havia atingido o \"Fim da História\", com a vitória definitiva da democracia liberal e do capitalismo de mercado."}'::jsonb, '[{"year":"1947","event":"Doutrina Truman e Plano Marshall marcam o início oficial da contenção da Guerra Fria."},{"year":"1961","event":"Construção do Muro de Berlim dividindo a capital alemã em dois setores ideológicos."},{"year":"1962","event":"Crise dos Mísseis de Cuba; momento de maior proximidade com a guerra nuclear total."},{"year":"1989 (9 Nov)","event":"Queda do Muro de Berlim; reunificação alemã consumada no ano seguinte (1990)."},{"year":"1991 (25 Dez)","event":"Dissolução oficial da União Soviética e fim da ordem geopolítica bipolar."}]'::jsonb, '[{"name":"Mikhail Gorbachev","role":"Último Líder da União Soviética","bio":"Promotor da Glasnost e Perestroika que permitiu a transição pacífica no Leste Europeu."},{"name":"Ronald Reagan","role":"Presidente dos EUA","bio":"Líder americano cujo discurso em Berlim (\"Mr. Gorbachev, tear down this wall!\") simbolizou a pressão ocidental."},{"name":"Helmut Kohl","role":"Chanceler da Alemanha","bio":"Arquiteto político da reunificação acelerada da Alemanha Ocidental e Oriental após a queda do muro."}]'::jsonb, '[{"id":"src-gf-1","title":"The Cold War: A New History","author":"John Lewis Gaddis","year":2005,"type":"book","details":"Penguin Press, Cap. 6-8"},{"id":"src-gf-2","title":"O Fim da História e o Último Homem","author":"Francis Fukuyama","year":1992,"type":"book","details":"Free Press"}]'::jsonb, 'published', true),
('descolonizacao-africa-asia', 'História', 'Idade Contemporânea', 'Descolonização da África, Ásia e Fim do Apartheid (1947–1994 d.C.)', 'Segunda Metade do Século XX (1947–1994 d.C.)', 'O desmantelamento dos impérios coloniais europeus na Ásia e África pós-Segunda Guerra. Destaque para a independência não-violenta da Índia sob Gandhi (1947) e a histórica queda do regime de segregação racial do Apartheid na África do Sul sob Nelson Mandela (1994).', 'high', '{"title":"A Não-Violência Ativa na Índia e a Vitória contra o Apartheid","description":"Após décadas de domínio da Coroa Britânica, Mahatma Gandhi liderou a resistência civil não-violenta (Satyagraha) e a Marcha do Sal, culminando na independência da Índia em 1947. Na África do Sul, o regime de segregação racial do Apartheid (instituído em 1948) foi desmontado após intensas sanções internacionais e a liderança de Nelson Mandela, eleito presidente em 1994."}'::jsonb, '{"title":"O Enfraquecimento Imperial e a Conferência de Bandung (1955)","description":"Historiadores da pós-colonialidade explicam que o esgotamento financeiro europeu após 1945 abriu espaço para o surgimento do \"Terceiro Mundo\" e do Movimento dos Não-Alinhados, articulado na Conferência de Bandung por líderes africanos e asiáticos."}'::jsonb, '{"title":"A Tese do Neocolonialismo de Kwame Nkrumah","description":"O líder ganes Kwame Nkrumah formulou a hipótese de que a independência política formal não libertou os países africanos, os quais permaneceram subordinados ao neocolonialismo econômico e às corporações do Norte Global."}'::jsonb, '[{"year":"1947","event":"Independência da Índia e do Paquistão, encerrando o Raj Britânico no subcontinente."},{"year":"1955","event":"Conferência de Bandung na Indonésia consagra o Movimento dos Países Não-Alinhados."},{"year":"1960","event":"O \"Ano da África\": 17 nações africanas conquistam a independência formal."},{"year":"1990","event":"Libertação de Nelson Mandela após 27 anos de prisão política na África do Sul."},{"year":"1994","event":"Primeiras eleições multirraciais na África do Sul e posse de Nelson Mandela como Presidente."}]'::jsonb, '[{"name":"Mahatma Gandhi","role":"Líder da Independência da Índia","bio":"Apostolo da não-violência e desobediência civil que inspirou movimentos de libertação no mundo todo."},{"name":"Nelson Mandela","role":"Presidente da África do Sul e Nobel da Paz","bio":"Líder do Congresso Nacional Africano que venceu o Apartheid e unificou a nação sul-africana."},{"name":"Kwame Nkrumah","role":"Pai do Pan-Africanismo e Presidente de Gana","bio":"Líder da primeira colônia da África Subsaariana a conquistar a independência (1957)."}]'::jsonb, '[{"id":"src-des-1","title":"Autobiografia: A Minha Vida e as Minhas Experiências com a Verdade","author":"Mahatma Gandhi","year":1927,"type":"book","details":"Tradução Crítica"},{"id":"src-des-2","title":"Long Walk to Freedom: The Autobiography of Nelson Mandela","author":"Nelson Mandela","year":1994,"type":"book","details":"Little, Brown and Company"}]'::jsonb, 'published', true),
('direitos-civis-eua-1960', 'História', 'Idade Contemporânea', 'O Movimento dos Direitos Civis nos Estados Unidos (Anos 1960)', 'Anos 1960 (1955–1968 d.C.)', 'A mobilização popular massiva contra as leis de segregação racial Jim Crow no Sul americano. Liderada por Martin Luther King Jr., Rosa Parks e Malcolm X, alcançou a aprovação histórica da Lei dos Direitos Civis de 1964 e da Lei do Direito ao Voto de 1965.', 'high', '{"title":"De Montgomery à Marcha sobre Washington (1963)","description":"Iniciado em 1955 com o boicote aos ônibus de Montgomery após a prisão de Rosa Parks, o movimento atingiu seu auge em 28 de agosto de 1963, quando 250.000 pessoas reuniram-se no Lincoln Memorial em Washington. Martin Luther King Jr. proferiu o histórico discurso \"I Have a Dream\", exigindo o fim da segregação racial e igualdade de oportunidades."}'::jsonb, '{"title":"Duas Correntes Estratégicas: Desobediência Não-Violenta vs. Autodefesa Negra","description":"A historiografia política analisa as correntes complementares e concorrentes do movimento: a estratégia do pastor Martin Luther King Jr. centrada na não-violência e integração nacional, em contraste com a postura do Poder Negro (Black Power) e Malcolm X, que pregavam o orgulho negro, autodeterminação e autodefesa contra a violência policial."}'::jsonb, '{"title":"A Vigilância do FBI e o Projeto COINTELPRO","description":"Documentos oficiais desclassificados do governo americano comprovaram que o FBI sob J. Edgar Hoover manteve vigilância ilegal sistemática (Operação COINTELPRO) para espionar, chantagear e desestabilizar as lideranças dos Direitos Civis."}'::jsonb, '[{"year":"1955","event":"Rosa Parks recusa ceder o assento no ônibus; início do Boicote dos Ônibus de Montgomery."},{"year":"1963","event":"Marcha sobre Washington reúne 250.000 pessoas e King profere \"I Have a Dream\"."},{"year":"1964","event":"O Presidente Lyndon B. Johnson assina a Lei dos Direitos Civis (Civil Rights Act)."},{"year":"1965","event":"Marcha de Selma a Montgomery e aprovação da Lei do Direito ao Voto (Voting Rights Act)."},{"year":"1968","event":"Assassinato de Martin Luther King Jr. em Memphis, disparando comoção e comoção nacional."}]'::jsonb, '[{"name":"Martin Luther King Jr.","role":"Pastor e Líder dos Direitos Civis","bio":"Prêmio Nobel da Paz que liderou a luta pela igualdade racial através da não-violência ativa."},{"name":"Rosa Parks","role":"Ativista dos Direitos Civis","bio":"Costureira cujo ato corajoso de recusa em Montgomery tornou-se o estopim do movimento civil moderno."},{"name":"Malcolm X (El-Hajj Malik El-Shabazz)","role":"Líder e Orador Nacionalista Negro","bio":"Defensor da autodeterminação, orgulho da identidade negra e crítico do racismo institucional."}]'::jsonb, '[{"id":"src-civ-1","title":"Carta da Prisão de Birmingham (Letter from Birmingham Jail)","author":"Martin Luther King Jr.","year":1963,"type":"document","details":"Texto fundamental da filosofia de desobediência civil"},{"id":"src-civ-2","title":"The Autobiography of Malcolm X","author":"Malcolm X e Alex Haley","year":1965,"type":"book","details":"Grove Press"}]'::jsonb, 'published', true)
